-- Easy Professions (Forever): guide texts in koKR (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("koKR", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "이 WoW Forever 연금술 숙련도 가이드는 연금술 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "아래에서 전체 구매 목록, 시작 지역과 수도별 연금술 전문기술 상급자, 그리고 수습부터 장인까지 숙련도 구간별로 가장 저렴한 제조법을 확인할 수 있어요. 연금술은 약초채집과 함께 하는 것이 가장 좋아요. 이 두 가지를 함께 하면 경매장에서 약초를 살 필요가 없어서 골드를 많이 아낄 수 있어요.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "이 내용은 Forever 베타를 기준으로 해요. 숙련도를 올리는 데 시간이 오래 걸려서 라이브 서버에서 높은 구간을 테스트하려면 시간이 좀 걸릴 거예요. 이상한 점을 발견하면 피드백을 보내 주세요.",
  ["Shopping List"] = "구매 목록",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "이 수치는 추정치예요. 제조법이 노란색이 되면 제작할 때마다 숙련도가 오르지 않으니 조금 더 필요하거나 덜 필요할 수 있어요.",
  ["Alchemy Trainer Locations"] = "연금술 전문기술 상급자 위치",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 연금술에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "모든 수도에 전문기술 상급자가 있어요. 경비병에게 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["Horde"] = "호드",
  ["Alliance"] = "얼라이언스",
  ["Capital Cities"] = "수도",
  ["Orgrimmar: {n:0:horde:Whuut}"] = "오그리마: {n:0:horde:Whuut}",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "언더시티: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "썬더 블러프: {n:0:horde:Kray}",
  ["Starting Zones"] = "시작 지역",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "모든 지역에 전문기술 상급자가 있는 것은 아니에요. 표에는 종족별로 가장 가까운 상급자가 나와 있어요.",
  ["Race"] = "종족",
  ["Zone"] = "지역",
  ["Closest trainer"] = "가장 가까운 상급자",
  ["Orc, Troll"] = "오크, 트롤",
  ["Durotar"] = "듀로타",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "센진 마을의 {n:0:horde:Miao'zan}",
  ["Tauren"] = "타우렌",
  ["Mulgore"] = "멀고어",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "멀고어에는 연금술 전문기술 상급자가 없어요. 썬더 블러프 중간 언덕의 {n:0:horde:Kray}에게 가세요",
  ["Undead"] = "언데드",
  ["Tirisfal Glades"] = "티리스팔 숲",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "브릴 북서쪽 끝 작은 집에 있는 {n:0:horde:Carolai Anise}",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "Valanaar의 {n:0::Iaadaria Bitterwind} 또는 {n:0::Valiena Swiftgale}, Shen'dar Village의 {n:0::Nyassa Swiftdraught}",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "스톰윈드: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "아이언포지: {n:0:alliance:Vosur Brakthel}",
  ["Darnassus: {n:0:alliance:Milla Fairancora}"] = "다르나서스: {n:0:alliance:Milla Fairancora}",
  ["Human"] = "인간",
  ["Elwynn Forest"] = "엘윈 숲",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "스톰윈드와 북녘골 사이 언덕에 있는 오두막의 {n:0:alliance:Alchemist Mallory}",
  ["Dwarf, Gnome"] = "드워프, 노움",
  ["Dun Morogh"] = "던 모로",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "던 모로에는 연금술 전문기술 상급자가 없어요. 아이언포지 땜장이 마을의 {n:0:alliance:Vosur Brakthel}에게 가세요",
  ["Night Elf"] = "나이트 엘프",
  ["Teldrassil"] = "텔드랏실",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "돌라나르 여관 동쪽 작은 집에 있는 {n:0:alliance:Cyndra Kindwhisper}",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "호드와 얼라이언스의 모든 연금술 전문기술 상급자는 제 WoW Forever 연금술 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice Alchemy (1-55)"] = "수습 연금술 (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 은엽수풀 9개, 빈 약병 9개",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "약병은 연금술 재료 상인과 잡화 상인이 팔아요. 대부분의 전문기술 상급자 근처에 상인이 있어요. 언더시티에서는 {n:0:horde:Algernon}이, 돌라나르에서는 {n:0:alliance:Narret Shadowgrove}가 가장 가까워요.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 은엽수풀 45개, 평온초 45개, 빈 약병 45개",
  ["Journeyman Alchemy (55-150)"] = "숙련 연금술 (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 연금술을 배우세요. {b}연금술 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["{b}Horde trainers:{/b}"] = "{b}호드 전문기술 상급자:{/b}",
  ["Orgrimmar: {n:0:horde:Yelmak}"] = "오그리마: {n:0:horde:Yelmak}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "언더시티: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "썬더 블러프: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}얼라이언스 전문기술 상급자:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "스톰윈드: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "아이언포지: {n:0:alliance:Tally Berryfizz}",
  ["Darnassus: {n:0:alliance:Sylvanna Forestmoon}"] = "다르나서스: {n:0:alliance:Sylvanna Forestmoon}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 마법초 10개, 평온초 10개, 빈 약병 10개",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 뱀뿌리 56개, 평온초 28개, 빈 약병 28개",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 마법초 30개, 찔레가시 60개, 빈 약병 30개",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "재봉술도 올린다면 이 비약은 보관하세요. Gloves of Meditation을 만들 때 필요해요.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 마법초 10개, 갈래물풀 10개, 빈 약병 10개",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 불지느러미 퉁돔 40개, 빈 약병 20개",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "한 번 제작할 때마다 오일이 2개 나와요. 그중 30개는 보관하세요. 다음 구간의 Elixir of Fire Power에 필요해요.",
  ["Expert Alchemy (150-225)"] = "전문 연금술 (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 언더시티의 {n:0:horde:Doctor Herbert Halsey}(호드) 또는 다르나서스의 {n:0:alliance:Ainethil}(얼라이언스)에게 가서 전문 연금술을 배우세요. {b}연금술 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 화염 오일 30개, 왕꽃잎풀 15개, 납 약병 15개",
  ["These are the Fire Oils you kept."] = "보관해 둔 화염 오일을 쓰면 돼요.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 갈래물풀 36개, 왕꽃잎풀 36개, 납 약병 36개",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 생명의 뿌리 36개, 갈래물풀 36개, 납 약병 36개",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion}은 아래 상인들이 팔아요. 획득 시 귀속이니 연금술을 올리는 캐릭터로 구매하세요:",
  ["{n:0:horde:Bronk} in Feralas"] = "페랄라스의 {n:0:horde:Bronk}",
  ["{n:0:alliance:Logannas} in Feralas"] = "페랄라스의 {n:0:alliance:Logannas}",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "가시덤불 골짜기의 {n:0::Glyx Brewright}",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "타나리스의 {n:0::Alchemist Pestlezugg}",
  ["Artisan Alchemy (225-300)"] = "장인 연금술 (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "225 이상을 배우려면 슬픔의 늪 스토나드의 {n:0:horde:Rogvar}(호드) 또는 페랄라스 페더문 요새의 {n:0:alliance:Kylanna Windwhisper}(얼라이언스)에게 가서 장인 연금술을 배우세요. {b}연금술 200{/b}과 {b}레벨 35{/b}가 필요해요.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 생명의 뿌리 26개, 갈래물풀 26개, 납 약병 26개",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 실명초 15개, 카드가의 수염 15개, 수정 약병 15개",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 돌비늘 뱀장어 47개, 납 약병 47개",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}모두 보관하세요{/b}. 한 번 제작하면 2개가 나오고, 265의 비약에 94개가 전부 필요해요.",
  ["Alternative recipe"] = "대체 제조법",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "{i:13422:inv_misc_fish_11:Stonescale Eel}이 비싸다면 이 단계를 건너뛰고 265까지 Elixir of Greater Intellect를 계속 만드세요(약 21개). 그다음 265-300 구간의 Superior Mana Potion을 만들면 돼요.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 실명초 10개, 카드가의 수염 10개, 수정 약병 10개",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 돌비늘 오일 94개, 태양풀 47개, 수정 약병 47개",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense}는 오그리마의 {n:0:horde:Kor'geld}와 아이언포지의 {n:0:alliance:Soolie Berryfizz}가 팔아요.",
  ["If you skipped the Stonescale Oil, make this:"] = "돌비늘 오일을 건너뛰었다면 이것을 만드세요:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 태양풀 110개, 실명초 110개, 수정 약병 55개.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion}은 언더시티의 {n:0:horde:Algernon}과 다르나서스의 {n:0:alliance:Ulthir}가 팔아요.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "이 WoW Forever 대장기술 숙련도 가이드는 대장기술 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "아래에서 전체 구매 목록, 시작 지역과 수도별 대장기술 전문기술 상급자, 그리고 수습부터 장인까지 숙련도 구간별로 가장 저렴한 제조법을 확인할 수 있어요. 대장기술은 광석을 많이 쓰기 때문에 채광과 함께 올리는 것을 추천해요. 경매장에서 모두 사려면 골드가 많이 필요해요.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "토륨 주괴에는 네 개의 퀘스트에 필요한 140개가 포함되어 있어요.",
  ["Blacksmithing Trainer Locations"] = "대장기술 전문기술 상급자 위치",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 대장기술에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "다르나서스를 제외한 모든 수도에 전문기술 상급자가 있어요. 경비병에게 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["Orgrimmar: {n:0:horde:Ug'thok}"] = "오그리마: {n:0:horde:Ug'thok}",
  ["Undercity: {n:0:horde:Basil Frye}"] = "언더시티: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "썬더 블러프: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "칼바위 언덕 대장간의 {n:0:horde:Dwukk}",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "멀고어에는 대장기술 전문기술 상급자가 없어요. 썬더 블러프 아래쪽 언덕의 {n:0:horde:Thrag Stonehoof}에게 가세요",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "Bandarion Keep의 {n:0:horde:Angus Hammerhand}. 근처에 {i:5956:inv_hammer_20:Blacksmith Hammer}를 파는 사람이 없으니 데스넬의 {n:0:horde:Walter Mason}이나 브릴의 {n:0:horde:Abigail Shiel}에게서 {b}가기 전에 미리 구매하세요{/b}.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "Valanaar의 {n:0::Daeann Steelwind}, Shen'dar Village의 {n:0::Aedi Thriceforged}",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "스톰윈드: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "아이언포지: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "골드샤이어 여관 맞은편의 {n:0:alliance:Smith Argus}",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "카라노스 썬더브루 양조장 맞은편의 {n:0:alliance:Tognus Flintfire}",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "텔드랏실과 다르나서스에는 대장기술 전문기술 상급자가 없어요. 가장 가까운 상급자는 어둠해안 아우버다인의 {n:0:alliance:Delfrum Flintbeard}예요",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "호드와 얼라이언스의 모든 대장기술 전문기술 상급자는 제 WoW Forever 대장기술 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice Blacksmithing (1-75)"] = "수습 대장기술 (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "대장기술을 배울 때 {i:5956:inv_hammer_20:Blacksmith Hammer}를 하나 사세요. 대부분의 도안에 필요하고, 숙련도를 올리면서 자신이 쓸 장비도 만들 수 있어요. 몇 코퍼밖에 안 해요. 아래에서 진영을 열어 전문기술 상급자와 가장 가까운 판매 상인을 확인하세요.",
  ["Horde vendors"] = "호드 상인",
  ["Vendor"] = "상인",
  ["Orgrimmar"] = "오그리마",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:horde:Sumi}",
  ["Undercity"] = "언더시티",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:horde:Samuel Van Brunt}",
  ["Thunder Bluff"] = "썬더 블러프",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:horde:Taur Stonehoof}",
  ["{n:0:horde:Flakk} in Razor Hill"] = "칼바위 언덕의 {n:0:horde:Flakk}",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "데스넬의 {n:0:horde:Walter Mason} 브릴의 {n:0:horde:Abigail Shiel}",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "Valanaar의 채광 전문기술 상급자 {n:0::Halavuul Cragwind} Shen'dar Village의 {n:0::Aedi Thriceforged}",
  ["Alliance vendors"] = "얼라이언스 상인",
  ["Stormwind City"] = "스톰윈드",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:alliance:Kaita Deepforge}",
  ["Ironforge"] = "아이언포지",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:alliance:Thurgrum Deepforge}",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "골드샤이어의 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "전문기술 상급자 바로 옆의 {n:0:alliance:Thrawn Boltar}",
  ["Darkshore"] = "어둠해안",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "아우버다인 전문기술 상급자 바로 옆의 {n:0:alliance:Elisa Steelhand}",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 거친 돌 30개",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 거친 돌 60개",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "그중 10개는 보관하세요. 75의 Silver Rod에 필요해요.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 투박한 돌 72개",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "36개를 모두 만드세요. 95와 112의 손목보호구에 필요해요.",
  ["If you are not at 75 after these, make a few more."] = "이것들을 만든 후에도 75가 안 됐다면 몇 개 더 만드세요.",
  ["Journeyman Blacksmithing (75-150)"] = "숙련 대장기술 (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 대장기술을 배우세요. {b}대장기술 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["Orgrimmar: {n:0:horde:Snarl}"] = "오그리마: {n:0:horde:Snarl}",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "언더시티: {n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "썬더 블러프: {n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "티리스팔 숲: Bandarion Keep의 {n:0:horde:Angus Hammerhand}",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "Zephras Isle: Valanaar의 {n:0::Daeann Steelwind}",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "스톰윈드: {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "아이언포지: {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 은 주괴 5개, 거친 연마석 10개",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "여기서부터는 {i:5956:inv_hammer_20:Blacksmith Hammer}가 필요해요.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "은 주괴 1개가 구리 주괴 10개보다 비싸다면 대신 5x {s:2666:inv_belt_03:Runed Copper Belt}(개당 구리 주괴 10개)를 만드세요.",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 구리 주괴 180개",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 청동 주괴 25개, 투박한 연마석 10개",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "50에서 만든 투박한 연마석 중 10개를 쓰고 나머지 26개는 112를 위해 보관하세요.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 무거운 돌 60개",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "보관하세요. 180의 Golden Scale Bracers에 20개가 모두 필요해요.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 청동 주괴 65개, 투박한 연마석 26개",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 청동 주괴 120개, 약한 융제 96개, 중간 가죽 48개",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "상인에게 Patterned Bronze Bracers보다 두 배 이상 비싸게 팔리기 때문에 결국 더 저렴해서 이것을 추천해요.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux}와 Bronze Warhammer(140-150)에 쓸 {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux}는 모든 수도의 대장기술 전문기술 상급자 바로 옆에 있는 대장기술 용품 상인이 팔아요.",
  ["If you disenchant your greens:"] = "녹색 아이템을 마력 추출한다면:",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 청동 주괴 120개, 투박한 연마석 48개.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 청동 주괴 80개, 강한 융제 10개, 중간 가죽 10개",
  ["Expert Blacksmithing (150-215)"] = "전문 대장기술 (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 오그리마의 {n:0:horde:Saru Steelfury}(호드) 또는 아이언포지의 {n:0:alliance:Bengus Deepforge}(얼라이언스)에게 가서 전문 대장기술을 배우세요. {b}대장기술 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 철 주괴 180개, 녹색 염료 30개",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "녹색 염료는 오그리마의 {n:0:horde:Tamar}와 아이언포지의 {n:0:alliance:Bombus Finespindle}가 팔아요.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 단단한 돌 32개",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "보관하세요. 210의 Heavy Mithril Axe에 6개가 필요해요.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 강철 주괴 100개, 무거운 연마석 40개",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "100에서 만든 무거운 연마석 20개를 쓰고 20개를 더 만드세요({i:2838:inv_stone_12:Heavy Stone} 60개).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "채광이 165라면 {i:3575:inv_ingot_iron:Iron Bar}와 {i:3857:inv_ore_tin_01:Coal}로 {i:3859:inv_ingot_steel:Steel Bars}를 직접 제련할 수 있어요. 석탄은 모든 수도의 대장기술 전문기술 상급자 옆에 있는 대장기술 용품 상인이 팔아요.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "얼라이언스 플레이어는 이 중 6개를 보관하세요. 방어구제작을 선택하면 필요할 수 있어요.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 미스릴 주괴 204개",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "상인에게 Heavy Mithril Gauntlets보다 세 배 이상 비싸게 팔리기 때문에 결국 더 저렴해서 이것을 추천해요.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 미스릴 주괴 72개, 황수정 12개, 단단한 연마석 6개, 두꺼운 가죽 24개",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "이 중 2개는 보관하세요. 무기제작을 선택하면 필요할 수 있어요.",
  ["Blacksmithing Specializations"] = "대장기술 전문화",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "{b}대장기술 200{/b}과 {b}레벨 40{/b}이 되면 방어구제작이나 무기제작으로 전문화해서 강력한 방어구나 무기를 만들 수 있어요. 선택은 자유이며, 대장기술을 올리는 데 필요하지 않고 나중에 선택해도 돼요.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "방어구제작자나 무기제작자가 되는 방법은 별도의 가이드를 참고하세요:",
  ["Artisan Blacksmithing (215-300)"] = "장인 대장기술 (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "225 이상을 배우려면 가시덤불 골짜기 무법항의 {n:0::Brikk Keencraft}에게 가서 장인 대장기술을 배우세요. {b}대장기술 200{/b}과 {b}레벨 35{/b}가 필요하고, 두 진영 모두 여기서 배워요.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs}는 필드 드롭이에요. 이미 가지고 있다면 대신 {b}Mithril Spurs{/b} 탭을 이용하세요.",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 미스릴 주괴 160개",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "이 중 2개는 보관하세요. 방어구제작을 선택하면 필요할 수 있어요.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 조밀한 돌 5개",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 미스릴 주괴 224개, 질긴 가죽 64개",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 토륨 주괴 110개, 튼튼한 가죽 30개, 아쿠아마린 5개",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "도안은 타나리스의 {n:14567::Derotain Mudsipper}에게서 받는 {q:7653::Imperial Plate Belt} 퀘스트({b}레벨 50{/b} 필요)로 얻을 수 있어요. 완료하려면 토륨 주괴 20개가 필요해요. 먼저 그의 {q:7652::A Blue Light Bargain} 퀘스트를 하세요. 이 퀘스트가 Imperial Plate 퀘스트들을 열어 줘요.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}다음 세 도안도 같은 NPC에게서 얻어요{/b}. 그러니 4개의 도안을 모두 얻으려면 토륨 주괴를 최소 140개 가져가세요.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "아래 필드 드롭 도안 중 하나가 있다면 240부터 대신 만들 수 있어요:",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 미스릴 주괴 378개, 아쿠아마린 27개, 작은 월장석 54개, 이끼 마노 54개, 단단한 연마석 27개, 마법 옷감 54개",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 미스릴 주괴 360개, 대지의 핵 40개, 단단한 연마석 20개, 질긴 가죽 80개",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 토륨 주괴 204개, 푸른 마력의 수정 68개",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 미스릴 주괴 40개, 단단한 연마석 30개(단단한 돌 120개)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 미스릴 주괴 132개, 단단한 연마석 99개(단단한 돌 396개)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}다음 세 도안은 모두 타나리스의 한 NPC에게서 얻어요{/b}. 그러니 3개의 도안을 모두 얻으려면 토륨 주괴를 최소 120개 가져가세요.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 토륨 주괴 540개, 별 루비 27개",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "도안은 타나리스의 {n:14567::Derotain Mudsipper}에게서 받는 {q:7655::Imperial Plate Bracer} 퀘스트({b}레벨 50{/b} 필요)로 얻어요. 완료하려면 토륨 주괴 20개가 필요해요.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 토륨 주괴 680개, 별 루비 20개, 아쿠아마린 20개",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "도안은 {q:7654::Imperial Plate Boots} 퀘스트로 얻으며, 토륨 주괴 40개가 필요해요.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}참고:{/b} 베타에서는 여기까지 올릴 수 없었기 때문에 이 부분은 게임 파일에서 찾은 데이터에만 기반해요. 아직 발견하지 못한 도안이 더 있을 수 있지만, 다른 것이 없다면 300까지 올리는 데 쓸 수 있는 도안은 이것뿐이에요.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 토륨 주괴 440개, 별 루비 20개",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "도안은 {q:7658::Imperial Plate Leggings} 퀘스트로 얻으며, 토륨 주괴 60개가 필요해요.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "이 WoW Forever 마법부여 숙련도 가이드는 마법부여 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "마법부여는 재봉술과 잘 어울려요. 둘 다 채집 전문기술이 필요 없고, 재봉술로 만든 아이템을 마력 추출할 수 있거든요. 아래에서 구매 목록, 시작 지역과 수도별 마법부여 전문기술 상급자, 그리고 숙련도 구간별로 가장 저렴한 마법부여를 확인할 수 있어요. Forever에는 저레벨 제조법이 몇 개 추가되어서 처음 70포인트는 클래식보다 저렴해요.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "대체 항목은 해당 줄 전체를 대체하니 더 저렴한 쪽을 구매하세요.",
  ["Enchanting Trainer Locations"] = "마법부여 전문기술 상급자 위치",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 마법부여에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["Orgrimmar: {n:0:horde:Jhag}"] = "오그리마: {n:0:horde:Jhag}",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "언더시티: {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "썬더 블러프: {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "센진 마을의 {n:0:horde:Pa'zula}",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "멀고어에는 마법부여 전문기술 상급자가 없어요. 썬더 블러프 중간 언덕의 {n:0:horde:Mot Dawnstrider}에게 가세요",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "브릴 여관 위층의 {n:0:horde:Vance Undergloom}",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "Valanaar의 {n:0::Eaysaa Brightgust}, Shen'dar Village의 {n:0::Nasalanna Windsinger}",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "스톰윈드: {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "아이언포지: {n:0:alliance:Thonys Pillarstone}",
  ["Darnassus: {n:0:alliance:Lalina Summermoon}"] = "다르나서스: {n:0:alliance:Lalina Summermoon}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "엘윈 숲에는 마법부여 전문기술 상급자가 없어요. 스톰윈드 마법사 지구의 {n:0:alliance:Betty Quin}에게 가세요",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "던 모로에는 마법부여 전문기술 상급자가 없어요. 아이언포지 거대한 용광로의 {n:0:alliance:Thonys Pillarstone}에게 가세요",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "텔드랏실 북서쪽 신탁의 숲에 있는 {n:0:alliance:Alanna Raveneye}",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "호드와 얼라이언스의 모든 마법부여 전문기술 상급자는 제 WoW Forever 마법부여 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Enchanting Macro for Faster Leveling"] = "더 빠른 숙련도 올리기를 위한 마법부여 매크로",
  ["I highly recommend using this macro to speed up the leveling process."] = "숙련도 올리는 속도를 높이려면 이 매크로를 꼭 사용해 보세요.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "이 매크로는 만들기 버튼을 대신 눌러 주고, 아이템에 이미 있는 마법부여를 교체할지 묻는 창도 추가 클릭 없이 확인해 줘요.",
  ["Macro"] = "매크로",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "매크로를 만들어 본 적이 없다면 채팅창에 /m을 입력하고 Enter를 누른 뒤, 새로 만들기를 클릭하고 이름을 정한 다음 이 두 줄을 붙여 넣으세요.",
  ["How to Use"] = "사용 방법",
  ["Place the macro on your action bar"] = "매크로를 행동 단축바에 올려놓으세요",
  ["Open your Enchanting profession window"] = "마법부여 전문기술 창을 여세요",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "만들 마법부여를 선택하세요(올바른 것인지 꼭 확인하세요)",
  ["Put the item you want to enchant into the optional target slot"] = "마법부여할 아이템을 선택 대상 칸에 넣으세요",
  ["Press the macro repeatedly"] = "매크로를 반복해서 누르세요",
  ["Disenchanting"] = "마력 추출",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "{s:13262:inv_enchant_disenchant:Disenchant}는 수습 마법부여와 함께 배워요. WoW Forever에서는 {b}마력 추출이 마법책에 없고{/b}, 전문기술 창의 마법부여 칸에 있어요.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "마력 추출 표를 찾고 있다면 제 마력 추출 가이드에 있어요. 마력 추출 버튼을 찾을 수 없다면 가이드에서 그림으로 보여 드려요:",
  ["Apprentice Enchanting (1-70)"] = "수습 마법부여 (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 구리 마법막대 1개, 마법의 티끌 1개",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "{i:6217:inv_misc_flute_01:Copper Rod}와 {i:247786:inv_elemental_mote_mana:Mote of Magic}은 전문기술 상급자 근처의 마법부여 용품 상인이 팔아요. 경매장에서 사지 마세요.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}저레벨 캐릭터로 시작 지역에서 숙련도를 올린다면{/b} 구리 마법막대는 그곳의 잡화 상인에게서 살 수 있지만, 마법의 티끌은 마법부여 상인만 팔아요. 시작 지역에서는 {b}Zephras Isle{/b}과 {b}티리스팔 숲{/b}(브릴)의 전문기술 상급자만 팔고, 나머지는 수도의 전문기술 상급자에게 가야 해요. 상인이 바로 옆에 있어요.",
  ["18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mote of Magic"] = "18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 마법의 티끌 18개",
  ["Make one of these:"] = "이 중 하나를 만드세요:",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 이상한 가루 50개",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 하급 마법의 정수 50개",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "{i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence}는 가방에서 오른쪽 클릭하면 하급 마법의 정수 3개로 바뀌니 이것을 사도 돼요.",
  ["Journeyman Enchanting (70-150)"] = "숙련 마법부여 (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 마법부여를 배우세요. {b}마법부여 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["Orgrimmar: {n:0:horde:Godan}"] = "오그리마: {n:0:horde:Godan}",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "언더시티: {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "썬더 블러프: {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "스톰윈드: {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "아이언포지: {n:0:alliance:Gimble Thistlefuzz}",
  ["Darnassus: {n:0:alliance:Taladan}"] = "다르나서스: {n:0:alliance:Taladan}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "이상한 가루를 샀다면 {b}이상한 가루{/b} 탭을, 하급 마법의 정수를 샀다면 {b}하급 마법의 정수{/b} 탭을 선택하세요.",
  ["Strange Dust"] = "이상한 가루",
  ["Lesser Magic Essence"] = "하급 마법의 정수",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 하급 마법의 정수 49개",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 은 마법막대 1개, 이상한 가루 3개, 하급 마법의 정수 4개, 어둠석 1개",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "{i:6338:inv_staff_01:Silver Rod}와 이 가이드의 다른 모든 마법막대(금, 진은, 아케이나이트)는 대장장이가 만들어요. 경매장에서 살 수 있어요.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 평범한 목재 23개, 하급 마법의 정수 46개",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 하급 마법의 정수 148개",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect}는 아래 상인들이 팔아요:",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "오그리마의 {n:0:horde:Kithas}",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "썬더 블러프의 {n:0:horde:Nata Dawnstrider}",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "은빛소나무 숲의 {n:0:horde:Leo Sarn}",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "아이언포지의 {n:0:alliance:Tilli Thistlefuzz}",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil}과 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}도 이 상인들에게서 사세요. 150과 200에서 필요해요.",
  ["If you don't want to get the formula, make this:"] = "주문식을 구하고 싶지 않다면 이것을 만드세요:",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 이상한 가루 100개",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 이상한 가루 23개",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 이상한 가루 30개",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 이상한 가루 18개",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 이상한 가루 64개",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 이상한 가루 80개",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "영혼 가루 20개가 이상한 가루 80개보다 싸다면 이것을 만드세요:",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 영혼 가루 20개.",
  ["Expert Enchanting (150-225)"] = "전문 마법부여 (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 전문 마법부여를 배우세요. {b}마법부여 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "전문 마법부여 전문기술 상급자는 진영마다 한 명뿐이에요. 호드는 돌발톱 산맥 태양바위 휴양지의 {n:0:horde:Hgarth}이며, 마을 위쪽 언덕에 있어요. 얼라이언스는 엘윈 숲의 {n:0:alliance:Kitta Firewind}이며, 아조라의 탑 꼭대기에 있어요.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 금 마법막대 1개, 무지갯빛 진주 1개, 상급 별의 정수 1개, 영혼 가루 1개",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 영혼 가루 16개, 단풍나무 씨앗 32개, 납 약병 16개",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil}은 아래 상인들이 팔아요:",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "언더시티의 {n:0:horde:Thaddeus Webb}",
  ["{n:0:alliance:Vaean} in Darnassus"] = "다르나서스의 {n:0:alliance:Vaean}",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "스톰윈드의 {n:0:alliance:Jessara Cordell}",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "{i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}도 이 상인들에게서 사세요. 200에서 필요해요.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed}는 마법 재료 상인이, {i:3372:inv_potion_85:Leaded Vial}은 연금술 재료 상인이 팔아요.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 영혼 가루 47개",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "환영 가루 2개가 영혼 가루 3개보다 싸다면 185에서 장화 마법부여를 멈추고 200까지 이것을 만드세요:",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 환영 가루 15개.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 진은 마법막대 1개, 검은 진주 1개, 상급 신비의 정수 1개, 환영 가루 1개",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 환영 가루 25개, 가시덤불 씨앗 50개, 납 약병 25개",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "아직 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}을 사지 않았다면, 판매 상인은 위의 151-165 단계에 나와 있어요.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed}는 마법 재료 상인이, {i:3372:inv_potion_85:Leaded Vial}은 연금술 재료 상인이 팔아요.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 환영 가루 5개",
  ["Artisan Enchanting (225-300)"] = "장인 마법부여 (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "전문 마법부여 전문기술 상급자는 225까지만 가르쳐 줘요. 225 이상을 배우려면 {b}레벨 35{/b}와 {b}마법부여 200{/b}이 필요하며, 울다만의 Annora에게서 장인 마법부여를 배워야 해요(찾는 방법은 아래에서 설명해요). {b}장인 마법부여를 가르치는 전문기술 상급자는 그녀뿐이에요.{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Annora만 가르치는 제조법이 몇 개 있으니 {b}모든 제조법을 배울 골드와 마법부여 250까지 올릴 재료를 충분히 챙겨 가세요{/b}. 그렇지 않으면 높은 제조법을 배우러 울다만에 다시 가야 해요. {i:11137:inv_enchant_dustvision:Vision Dust} 약 50개면 250까지 올릴 수 있어요.",
  ["How to enter Uldaman"] = "울다만 입장 방법",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "울다만은 황야의 땅에 있으며 입구가 두 개예요. 뒤쪽 입구를 이용하세요. 레벨 35로는 혼자 갈 수 없으니 파티와 함께 가거나 레벨 60에게 도움을 요청하세요.",
  ["How to find Annora"] = "Annora 찾는 방법",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Annora는 {b}그녀가 있는 구역의 몹을 모두 처치해야만{/b} 나타나요!",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}울다만을 떠나기 전에 Annora에게서 모든 것을 배우는 것을 잊지 마세요!{/b} 230 이상의 제조법은 다른 곳에서는 배울 수 없어요.",
  ["Recipe"] = "제조법",
  ["Skill"] = "숙련도",
  ["Cost"] = "비용",
  ["{b}Artisan Enchanting{/b}"] = "{b}장인 마법부여{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 환영 가루 37개",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 꿈 가루 20개, 보라 연꽃 20개, 수정 약병 20개",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil}은 실리더스의 {n:0::Kania}가 팔며, 여관 위층에 있어요. {i:8925:inv_potion_86:Crystal Vial}은 실리더스의 {n:0::Mishta}나 연금술 재료 상인이 팔아요.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "보라 연꽃이 없다면 대신 {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength}(개당 꿈 가루 1개, 하급 황천의 정수 2개)를 만드세요. Annora가 가르쳐 줘요.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 꿈 가루 240개",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina}는 언더시티의 {n:0:horde:Daniel Bartlett}와 다르나서스의 {n:0:alliance:Mythrin'dir}가 팔아요. 획득 시 귀속이니 부캐릭터로 사지 마세요.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "290부터 Runed Arcanite Rod를 만들 수 있어요. 다음 단계를 보세요.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 아케이나이트 마법막대 1개, 황금 진주 1개, 환각 가루 10개, 상급 영원의 정수 4개, 작은 찬란한 결정 4개, 큰 찬란한 결정 2개",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod}는 달의 숲 나이트헤이븐의 {n:0::Lorelae Wintersong}가 팔아요.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}이 마법막대는 290부터 일부 제조법과 300의 대부분 제조법에 필요해요{/b}(예: 성전사). 290부터 만들 수 있지만 아직 필요하지 않다면 나중에 만들고, 마지막 1포인트는 방패 마법부여를 하나 더 해서 채워도 돼요.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "이 WoW Forever 기계공학 숙련도 가이드는 기계공학 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "기계공학은 채광과 함께 하는 것이 가장 좋아요. 만드는 거의 모든 것에 돌과 주괴가 필요한데, 둘 다 채광으로 얻을 수 있거든요. 채광이 없다면 모두 경매장에서 사야 해요. 아래에서 구매 목록, 시작 지역과 수도별 기계공학 전문기술 상급자, 그리고 숙련도 구간별로 가장 저렴한 설계도를 확인할 수 있어요.",
  ["Engineering Trainer Locations"] = "기계공학 전문기술 상급자 위치",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 기계공학에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "썬더 블러프와 다르나서스에는 기계공학 전문기술 상급자가 없고, 나머지 네 수도에는 있어요. 경비병에게 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["Orgrimmar: {n:0:horde:Thund}"] = "오그리마: {n:0:horde:Thund}",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "언더시티: {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "칼바위 언덕, 오그리마로 가는 길 옆 대장간 근처의 {n:0:horde:Mukdrak}",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "투자개발회사 광산 위 고원의 {n:0::Twizwick Sprocketgrind}. 저레벨에는 가기 어려워요. 근처에 모루가 없고 대장장이 망치를 파는 사람도 없으니 대신 오그리마의 {n:0:horde:Thund}에게 가는 것이 좋을 거예요.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "티리스팔 숲에는 기계공학 전문기술 상급자가 없어요. 언더시티 도적 지구의 {n:0:horde:Graham Van Talen}에게 가세요",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "Shadowgale Forest의 {n:0::Strange Hermit}",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "스톰윈드: {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "아이언포지: {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "엘윈 숲에는 기계공학 전문기술 상급자가 없어요. 스톰윈드 드워프 지구의 {n:0:alliance:Sprite Jumpsprocket}에게 가세요",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "스틸그릴 정비소의 {n:0:alliance:Bronk Guzzlegear}",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "텔드랏실과 다르나서스에는 기계공학 전문기술 상급자가 없어요. 가장 가까운 상급자는 어둠해안 아우버다인의 {n:0:alliance:Jenna Lemkenilli}예요",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "호드와 얼라이언스의 모든 기계공학 전문기술 상급자는 제 WoW Forever 기계공학 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice Engineering (1-50)"] = "수습 기계공학 (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "{i:5956:inv_hammer_20:Blacksmith Hammer}를 하나 사세요. 대부분의 설계도에 필요해요. {b}대부분의 전문기술 상급자{/b} 근처에는 이것을 파는 대장기술 또는 기계공학 용품 상인이 있지만, 던 모로와 Zephras Isle의 상급자는 {b}예외예요{/b}. 던 모로에서는 카라노스의 {n:0:alliance:Thrawn Boltar}에게서, Zephras Isle에서는 Shen'dar Village의 {n:0::Aedi Thriceforged}에게서 사세요.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "Forever에서 {b}노움{/b} 종족 특성이 바뀌었어요. 기계공학 숙련도 +15 대신, 기계공학 전문화가 이제 장치의 실패나 오작동 확률을 20% 줄여 줘요. 그래서 노움도 다른 종족과 똑같이 기계공학을 올려요.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 거친 돌 66개",
  ["Keep all of them, you need 66 for the bombs at 51."] = "모두 보관하세요. 51의 폭탄에 66개가 필요해요.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 구리 주괴 33개",
  ["Keep these too, you will need all 33 for the bombs."] = "이것도 보관하세요. 폭탄에 33개가 모두 필요해요.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 구리 주괴 6개",
  ["You will use this to craft Engineering recipes, so keep it."] = "기계공학 설계도를 제작할 때 쓰니 보관하세요.",
  ["Journeyman Engineering (50-150)"] = "숙련 기계공학 (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 기계공학을 배우세요. {b}기계공학 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["Orgrimmar: {n:0:horde:Nogg}"] = "오그리마: {n:0:horde:Nogg}",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "언더시티: {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "스톰윈드: {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "아이언포지: {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "그늘숲: {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 구리 주괴 33개, 구리 나사 한 줌 33개, 거친 화약 66개, 리넨 옷감 33개",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}이것으로 75를 넘길 수도 있어요{/b}. 그러니 숙련 기계공학을 이미 배우지 않았다면 자리비움 상태로 제작하지 않는 것이 좋아요. 먼저 배우거나, 자리비움 제작을 하지 마세요. (운에 따라 다르며, 75에 도달하지 못할 때도 있어요.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 투박한 돌 60개",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "보관하세요. 90의 다이너마이트에 60개가 모두 필요해요.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 투박한 화약 60개, 리넨 옷감 20개",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 은 주괴 5개",
  ["If Silver Bar is expensive, make this instead:"] = "은 주괴가 비싸다면 대신 이것을 만드세요:",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 얇은 가죽 30개, 호안석 10개.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 청동 주괴 50개, 약한 융제 25개",
  ["Keep 10 of them, you will need them at 125."] = "그중 10개는 보관하세요. 125에서 필요해요.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux}는 전문기술 상급자 근처의 기계공학 용품 상인이 팔아요.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "125에 몇 포인트 모자라도 관을 더 만들지 말고 그냥 조준경을 시작하세요.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 청동 관 10개, 이끼 마노 10개",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "이끼 마노가 없거나 너무 비싸다면 대신 {s:3945:inv_misc_dust_06:Heavy Blasting Powder}를 만들기 시작하세요.",
  ["Make both of these:"] = "둘 다 만드세요:",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 무거운 돌 30개",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 청동 주괴 30개, 양모 옷감 15개",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}반드시 같은 순서로 만드세요.{/b} 160의 양에 둘 다 필요하니 지금 만들면 이것으로 150에 도달할 거예요.",
  ["Expert Engineering (150-200)"] = "전문 기계공학 (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 오그리마의 {n:0:horde:Roxxik}(호드) 또는 아이언포지의 {n:0:alliance:Springspindle Fizzlegear}(얼라이언스)에게 가서 전문 기계공학을 배우세요. {b}기계공학 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 청동 주괴 30개, 중간 가죽 15개, 양모 옷감 15개",
  ["Keep these too, you will need all 15 for the sheep."] = "이것도 보관하세요. 양에 15개가 모두 필요해요.",
  ["The 15 will probably take you past 160, that's fine."] = "15개를 만들면 아마 160을 넘길 텐데, 괜찮아요.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 무거운 화약 30개, 윙윙거리는 청동 장치 15개, 청동 골격 15개, 양모 옷감 30개",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "그중 5개는 보관하세요. 200에서 고블린 기계공학을 선택하면 필요할 수 있어요.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 단단한 돌 120개",
  ["Save these, you will need them later."] = "나중에 필요하니 보관하세요.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 강철 주괴 4개",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "일부 기계공학 설계도를 제작할 때 필요하니 보관하세요.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "숙련도 운이 나빠서 195에 도달하지 못했다면 {s:3962:inv_misc_bomb_08:Iron Grenade}나 숙련도가 오르는 다른 설계도를 몇 개 만드세요.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 미스릴 주괴 18개",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "6개 모두 보관하세요. 200에서 노움 기계공학을 선택하면 필요할 수 있어요.",
  ["Engineering Specializations"] = "기계공학 전문화",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "{b}기계공학 200{/b}과 {b}레벨 30{/b}이 되면 노움 기계공학이나 고블린 기계공학으로 전문화할 수 있어요. 일부 아이템은 특정 전문화가 있어야 사용할 수 있고, 다른 아이템은 한 전문화만 만들 수 있지만 모든 기계공학자가 사용할 수 있어요. 다행히 한 전문화가 만드는 대부분의 아이템은 양쪽 모두 사용할 수 있어요.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "전문화를 선택하는 방법은 별도의 가이드를 참고하세요:",
  ["Artisan Engineering (200-300)"] = "장인 기계공학 (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "225 이상을 배우려면 {b}기계공학 200{/b}과 {b}레벨 35{/b}가 필요하며, 타나리스 가젯잔의 {n:0::Buzzek Bracketswing}에게서 장인 기계공학을 배워야 해요. 여관 바로 밖 우체통 근처에 있어요. 200 이상의 설계도도 그가 가르쳐 주니 200이 되면 바로 가세요.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 미스릴 주괴 20개, 마법 옷감 20개, 단단한 화약 20개",
  ["Keep them, you will need all 20 for the bombs at 238."] = "보관하세요. 238의 폭탄에 20개가 모두 필요해요.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 미스릴 주괴 120개",
  ["Keep these too, you will need 40 for the bombs."] = "이것도 보관하세요. 폭탄에 40개가 필요해요.",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 미스릴 외피 40개, 불안정한 기폭장치 20개, 단단한 화약 40개",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 조밀한 돌 88개",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 토륨 주괴 105개, 룬매듭 옷감 35개",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget}은 오그리마의 {n:0:horde:Sovik}와 아이언포지의 {n:0:alliance:Gearcutter Cogspinner}가 팔아요.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 토륨 주괴 120개",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube}는 여명의 설원 눈망루 마을의 {n:0::Xizzer Fizzbolt}가 팔며, 정문을 지나 오른쪽 첫 번째 건물에 있어요. Forever에서는 획득 시 귀속이니 기계공학을 올리는 캐릭터로 구매하세요.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "이 WoW Forever 가죽세공 숙련도 가이드는 가죽세공 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "아래에서 전체 구매 목록, 시작 지역과 수도별 가죽세공 전문기술 상급자, 그리고 수습부터 장인까지 숙련도 구간별로 가장 저렴한 도안을 확인할 수 있어요. 가죽이 비용의 대부분을 차지하기 때문에 가죽세공은 무두질과 함께 하는 것이 가장 좋지만, 가이드의 모든 재료를 경매장에서 살 수도 있어요.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "도안이 노란색이나 녹색일 때는 제작해도 항상 숙련도가 오르지는 않아서, 재료가 정확히 얼마나 필요한지 아무도 알 수 없어요. 그래서 운에 많이 좌우되는 수량은 범위로 표시했어요. {b}큰 숫자면 10명 중 9명은 충분하고, 작은 숫자면 반반이에요.{/b} 작은 숫자만큼 산다면 나중에 더 살 준비를 하세요.",
  ["Material"] = "재료",
  ["Leatherworking Trainer Locations"] = "가죽세공 전문기술 상급자 위치",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 가죽세공에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["Orgrimmar: {n:0:horde:Kamari}"] = "오그리마: {n:0:horde:Kamari}",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "언더시티: {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "썬더 블러프: {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "듀로타에는 가죽세공 전문기술 상급자가 없어요. 오그리마 골목길의 {n:0:horde:Kamari}에게 가세요",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "블러드후프 마을의 {n:0:horde:Chaw Stronghide}",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "브릴 남동쪽 갈림길의 {n:0:horde:Shelene Rhobart}",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "Valanaar의 {n:0::Emerii Tallgust}, Shen'dar Village의 {n:0::Indari Sunseam}",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "스톰윈드: {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "아이언포지: {n:0:alliance:Gretta Finespindle}",
  ["Darnassus: {n:0:alliance:Darianna}"] = "다르나서스: {n:0:alliance:Darianna}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "골드샤이어 북동쪽, 수정 호수 옆 작은 집의 {n:0:alliance:Adele Fielder}",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "던 모로에는 가죽세공 전문기술 상급자가 없어요. 아이언포지 거대한 용광로의 {n:0:alliance:Gretta Finespindle}에게 가세요",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "다르나서스로 가는 길 근처 작은 집의 {n:0:alliance:Nadyia Maneweaver}",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "호드와 얼라이언스의 모든 가죽세공 전문기술 상급자는 제 WoW Forever 가죽세공 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice Leatherworking (1-55)"] = "수습 가죽세공 (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 망가진 가죽 조각 105개",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 얇은 짐승 가죽 27개, 소금 27개",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}참고:{/b} {b}대부분의 전문기술 상급자{/b} 근처에는 실, 염료, 소금을 파는 가죽세공 용품 상인이 있지만, 엘윈 숲과 티리스팔 숲의 상급자는 {b}예외예요{/b}. 이 경우 소금과 거친 실은 골드샤이어의 {n:0:alliance:Tharynn Bouden}이나 브릴의 {n:0:horde:Abigail Shiel}에게서 사세요.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "짐승 가죽 중 24개는 보관하세요. 100의 Light Leather Pants에 필요해요.",
  ["Alternative recipes"] = "대체 도안",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "가죽을 직접 모으는데 얇은 짐승 가죽이 27개가 없다면, 45까지 Light Armor Kit를 만들고 55까지 Embossed Leather Gloves를 만드세요:",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 얇은 가죽 24개",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 얇은 가죽 30개, 거친 실 20개",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "100의 Light Leather Pants에는 여전히 처리된 얇은 짐승 가죽 24개가 필요하니, 그때까지 무두질로 얻은 얇은 짐승 가죽을 보관하세요.",
  ["Journeyman Leatherworking (55-130)"] = "숙련 가죽세공 (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 가죽세공을 배우세요. {b}가죽세공 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["Orgrimmar: {n:0:horde:Karolek}"] = "오그리마: {n:0:horde:Karolek}",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "언더시티: {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "썬더 블러프: {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "스톰윈드: {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "아이언포지: {n:0:alliance:Fimble Finespindle}",
  ["Darnassus: {n:0:alliance:Faldron}"] = "다르나서스: {n:0:alliance:Faldron}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 얇은 가죽 63개, 거친 실 42개",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 얇은 가죽 32개",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 중간 짐승 가죽 10개, 소금 10개",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "처리된 중간 짐승 가죽은 보관하세요. 115의 Dark Leather Belt에 필요해요.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 얇은 가죽 114개, 거친 실 38개",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "115의 Dark Leather Belt를 위해 허리띠 10개는 보관하세요.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 얇은 가죽 240개, 처리된 얇은 짐승 가죽 24개, 고급 실 24개",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 고급 가죽 허리띠 10개, 처리된 중간 짐승 가죽 10개, 고급 실 20개, 회색 염료 10개",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 중간 가죽 35개",
  ["Expert Leatherworking (130-205)"] = "전문 가죽세공 (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 썬더 블러프의 {n:0:horde:Una}(호드) 또는 다르나서스의 {n:0:alliance:Telonis}(얼라이언스)에게 가서 전문 가죽세공을 배우세요. {b}가죽세공 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 두꺼운 짐승 가죽 30개, 소금 90개",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "처리된 두꺼운 짐승 가죽은 보관하세요. 155의 Barbaric Shoulders에 10개, 165의 Guardian Gloves에 20개가 필요해요.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 중간 가죽 238개, 고급 실 68개",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 두꺼운 가죽 80개, 처리된 두꺼운 짐승 가죽 10개, 고급 실 20개",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 두꺼운 가죽 80개, 처리된 두꺼운 짐승 가죽 20개, 비단실 20개",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 질긴 가죽 110개, 비단실 44개",
  ["Leatherworking Specializations"] = "가죽세공 전문화",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "{b}가죽세공 225{/b}와 {b}레벨 40{/b}이 되면 세 가지 가죽세공 전문화 중 하나를 선택할 수 있어요: 용비늘, 원소, 전통. 각 전문화마다 특정 도안을 배울 수 있어요.",
  ["Dragonscale - Mail-type gear"] = "용비늘 - 사슬 장비",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "원소 - 원소 저항 및 가죽 민첩성 장비",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "전통 - 가죽 지능 및 민첩성 장비와 데빌사우루스 방어구 세트",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "용비늘, 원소, 전통 가죽세공사가 되는 방법은 별도의 가이드를 참고하세요:",
  ["Artisan Leatherworking (205-300)"] = "장인 가죽세공 (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "225 이상을 배우려면 페랄라스 모자케 야영지의 {n:0:horde:Hahrana Ironhide}(호드) 또는 동부 내륙지 맹금의 봉우리의 {n:0:alliance:Drakk Stonehand}(얼라이언스)에게 가서 장인 가죽세공을 배우세요. {b}가죽세공 200{/b}과 {b}레벨 35{/b}가 필요해요.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 질긴 가죽 504개, 비단실 144개",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}썬더 블러프와 다르나서스의 전문 단계 전문기술 상급자는 이 도안을 가르치지 않아요{/b}. 위의 두 상급자에게서만 배울 수 있어요.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "상인에게 Nightscape Boots보다 비싸게 팔리기 때문에 결국 더 저렴해서 이것을 추천해요.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 튼튼한 가죽 288개, 검은색 염료 36개, 룬 실 36개",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "도안은 티리스팔 숲의 {n:0:horde:Werg Thickblade}(호드)와 서부 역병지대의 {n:0:alliance:Leonard Porter}(얼라이언스)가 팔아요.",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Blue Suede Shoes는 같은 가죽을 쓰지만 상인에게 더 비싸게 팔려서 이 단계에서 약 13골드를 아낄 수 있어요. 경매장에서 도안이 그보다 싸다면 대신 이것을 만드세요:",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 튼튼한 가죽 288개, 파란색 염료 36개, 룬 실 36개.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 튼튼한 가죽 742개, 룬매듭 옷감 530개, 룬 실 53개",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "도안은 동부 역병지대 희망의 빛 예배당의 {n:0::Jase Farlane}가 팔아요.",
  ["If you have the pattern, make these from 275 instead:"] = "도안이 있다면 275부터 대신 이것을 만드세요:",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 튼튼한 가죽 270개, 파란색 염료 27개, 룬 실 27개.",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}가죽세공 300인 사람이 재봉틀을 설치해 줘야 해요.{/b} 재봉틀을 사더라도 300 전에는 직접 설치할 수 없어요. 블리자드의 실수인지 확실하지 않아서 바뀔 수도 있어요.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "재봉틀을 쓸 수 있고 도안이 있다면 280부터 이것을 만들 수 있어요:",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 튼튼한 가죽 320개, 파란색 염료 80개, 룬 실 20개.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "이 WoW Forever 재봉술 숙련도 가이드는 재봉술 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "아래에서 전체 구매 목록, 시작 지역과 수도별 재봉술 전문기술 상급자, 그리고 수습부터 장인까지 숙련도 구간별로 가장 저렴한 도안을 확인할 수 있어요. 재봉술은 옷감을 주재료로 쓰는데, 옷감은 인간형 몹에게서 나오기 때문에 채집 전문기술이 필요 없고 어떤 전문기술과도 함께할 수 있어요. 숙련도를 올리면서 만든 아이템을 마력 추출하고 그 가루로 마법부여를 올릴 수 있어서 마법부여가 인기 있는 선택이에요.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}참고:{/b} {b}대부분의 전문기술 상급자{/b} 근처에는 실과 염료를 파는 재봉술 용품 상인이 있지만, 티리스팔 숲의 상급자는 {b}예외예요{/b}. 이 경우 거친 실은 브릴의 {n:0:horde:Abigail Shiel}에게서 사세요.",
  ["Alternative (if cheaper)"] = "대체 항목 (더 저렴할 경우)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "이 목록은 아직 최종본이 아니지만 숙련도 구간은 게임 데이터에서 가져온 것이라 꽤 정확할 거예요. 280-300 구간은 아직 여기에 포함되지 않았어요.",
  ["Tailoring Trainer Locations"] = "재봉술 전문기술 상급자 위치",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "Forever에서는 수습 재봉술에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요.",
  ["Orgrimmar: {n:0:horde:Snang}"] = "오그리마: {n:0:horde:Snang}",
  ["Undercity: {n:0:horde:Victor Ward}"] = "언더시티: {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "썬더 블러프: {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "듀로타에는 재봉술 전문기술 상급자가 없어요. 오그리마 골목길의 {n:0:horde:Snang}에게 가세요",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "멀고어에는 재봉술 전문기술 상급자가 없어요. 썬더 블러프 중간 언덕의 {n:0:horde:Vhan}에게 가세요",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "브릴 남서쪽 콜드하스 장원의 작은 집에 있는 {n:0:horde:Bowen Brisboise}",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "Valanaar의 {n:0::Othesia Evengale}, Shen'dar Village의 {n:0::Taleen Shimmerthread}",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "스톰윈드: {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "아이언포지: {n:0:alliance:Uthrar Threx}",
  ["Darnassus: {n:0:alliance:Trianna}"] = "다르나서스: {n:0:alliance:Trianna}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "동부골짜기 벌목장의 집에 있는 {n:0:alliance:Eldrin}",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "던 모로에는 재봉술 전문기술 상급자가 없어요. 아이언포지 거대한 용광로의 {n:0:alliance:Uthrar Threx}에게 가세요",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "텔드랏실에는 재봉술 전문기술 상급자가 없어요. 다르나서스 장인의 정원의 {n:0:alliance:Trianna}에게 가세요",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "호드와 얼라이언스의 모든 재봉술 전문기술 상급자는 제 WoW Forever 재봉술 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice Tailoring (1-55)"] = "수습 재봉술 (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 리넨 옷감 60개",
  ["Keep the bolts, you need all of them for the belts."] = "두루마리는 보관하세요. 허리띠에 전부 필요해요.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 리넨 두루마리 28개, 거친 실 28개",
  ["Journeyman Tailoring (55-140)"] = "숙련 재봉술 (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "75 이상을 배우려면 아래 전문기술 상급자 중 한 명에게 가서 숙련 재봉술을 배우세요. {b}재봉술 50{/b}과 {b}레벨 10{/b}이 필요해요:",
  ["Orgrimmar: {n:0:horde:Magar}"] = "오그리마: {n:0:horde:Magar}",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "언더시티: {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "썬더 블러프: {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "스톰윈드: {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "아이언포지: {n:0:alliance:Jormund Stonebrow}",
  ["Darnassus: {n:0:alliance:Me'lynn}"] = "다르나서스: {n:0:alliance:Me'lynn}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}이것을 만들기 전에 숙련 재봉술을 배우세요.{/b} 이것으로 75를 넘길 수 있지만, 배우기 전까지는 75 이상에서 숙련도가 오르지 않으니 배우기 전에는 자리를 비운 채 제작하지 마세요.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 양모 옷감 135개",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "두루마리는 나중에 필요하니 보관하세요. 140까지 총 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} 153개({i:2592:inv_fabric_wool_01:Wool Cloth} 459개)가 필요하니 지금 전부 만들어도 돼요.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 양모 두루마리 22개, 고급 실 22개",
  ["If the bolts already took you past 80, just make capes until 95."] = "두루마리로 이미 80을 넘겼다면 95까지 망토만 만드세요.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 양모 두루마리 15개, 고급 실 10개",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 비단 옷감 216개",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "두루마리는 나중에 필요하니 보관하세요. 190까지 총 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} 184개({i:4306:inv_fabric_silk_01:Silk Cloth} 736개)가 필요하니 지금 전부 만들어도 돼요.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 양모 두루마리 116개, 고급 실 87개, 지혜의 비약 29개",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "{i:3383:inv_potion_06:Elixir of Wisdom}는 경매장에서 사거나 연금술사에게 부탁하세요.",
  ["Expert Tailoring (140-200)"] = "전문 재봉술 (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "150 이상을 배우려면 언더시티의 {n:0:horde:Josef Gregorian}(호드) 또는 스톰윈드의 {n:0:alliance:Georgio Bolero}(얼라이언스)에게 가서 전문 재봉술을 배우세요. {b}재봉술 125{/b}와 {b}레벨 20{/b}이 필요하고, 비용은 50실버예요.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 마법 옷감 115개",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "두루마리는 나중에 필요하니 보관하세요. 225까지 총 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} 157개({i:4338:inv_fabric_mageweave_01:Mageweave Cloth} 785개)가 필요하니 지금 전부 만들어도 돼요.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 비단 두루마리 80개, 붉은색 염료 40개, 고급 실 40개",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 비단 두루마리 104개, 붉은색 염료 52개, 비단실 52개",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 마법 두루마리 38개, 비단실 57개",
  ["Artisan Tailoring (200-300)"] = "장인 재봉술 (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "225 이상을 배우려면 힐스브래드 구릉지 타렌 밀농장의 {n:0:horde:Daryl Stack}(호드) 또는 먼지진흙 습지대 테라모어 섬의 {n:0:alliance:Timothy Worthington}(얼라이언스)에게 가서 장인 재봉술을 배우세요. {b}재봉술 200{/b}과 {b}레벨 35{/b}가 필요해요.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 마법 두루마리 15개, 굵은 비단실 10개",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}언더시티와 스톰윈드의 전문 단계 전문기술 상급자는 이 도안을 가르치지 않아요{/b}. 위의 두 상급자에게서만 배울 수 있어요.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 룬매듭 옷감 115개",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "두루마리는 나중에 필요하니 보관하세요. 280까지 총 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} 311개({i:14047:inv_fabric_purplefire_01:Runecloth} 1555개)가 필요하니 지금 전부 만들어도 돼요.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 마법 두루마리 104개, 비단실 52개",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "지금은 단순히 더 유용하기 때문에 가방을 추천해요. 직접 쓰거나, 일부를 팔거나, 친구에게 주거나, 은행에서 쓸 수 있어요.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "가방이 필요 없고 팔 생각도 없다면 대신 이것을 만드세요.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 룬매듭 두루마리 30개, 룬 실 10개.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 룬매듭 두루마리 72개, 룬 실 24개",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 룬매듭 두루마리 44개, 튼튼한 가죽 44개, 룬 실 11개",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "도안은 여명의 설원의 {n:0::Qia}가 팔아요.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 룬매듭 두루마리 195개, 강철그물 거미줄 39개, 룬 실 39개",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "도안은 하이잘 산의 {n:0::Pexmit}가 팔아요. 획득 시 귀속이니 재봉술을 올리는 캐릭터로 구매하세요.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "호드 플레이어는 하이잘 산 Elderwild의 {n:265788::Kal'tinzan}이 주는 퀘스트 {q:95769::Threading a Solution}의 보상으로도 얻을 수 있어요. 레벨 54와 룬매듭 두루마리 6개가 필요해요. 아마 재봉술 퀘스트일 텐데, 필요한 숙련도는 아직 모르겠어요.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "도안을 구할 수 있다면 {s:18449:inv_shoulder_21:Runecloth Shoulders}를 만드세요. 지금까지 찾은 것 중 280 이후에도 숙련도가 오르는 도안은 이것이 전부예요. 숙련도 올리기에 가치가 없는 것은 뺐고, 아직 아무도 찾지 못한 새 도안이 있을 수도 있어요.",
  ["Range"] = "구간",
  ["Materials"] = "재료",
  ["Pattern"] = "도안",
  ["World drop, on the Auction House"] = "필드 드롭, 경매장에서 구매",
  ["Rare, grab it if you see it on the Auction House"] = "희귀해요. 경매장에서 보이면 바로 사세요",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "이것으로 몇 포인트 더 올릴 수 있지만 300 전에 숙련도가 오르지 않게 되니 300에 도달할 수는 없어요:",
  ["{n:0::Pexmit} in Mount Hyjal"] = "하이잘 산의 {n:0::Pexmit}",
  ["Recipes that need a Loom"] = "베틀이 필요한 도안",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}이 도안들은 베틀이 필요한데, 베틀은 재봉술 300이 되어야 만들 수 있어요.{/b} 숙련도 올리기에 쓸 수 있지만, 지금은 다른 재봉사가 이미 베틀을 설치해 둔 야영지가 필요해요. 블리자드의 실수인지 확실하지 않아서 바뀔 수도 있어요.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "실리더스의 {n:0::Mishta}에게서 얻는 세나리온 의회 도안이에요:",
  ["Requires"] = "요구 사항",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} 또는 {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} 또는 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "세나리온 의회 약간 우호적",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} 또는 {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} 또는 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "세나리온 의회 우호적",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} 또는 {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} 또는 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "이 WoW Forever 채광 숙련도 가이드는 채광 숙련도를 1에서 300까지 가장 빠르게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "아래에서 시작 지역과 수도별 채광 전문기술 상급자, 그리고 숙련도 구간별로 채광하기 가장 좋은 지역을 확인할 수 있어요. 채광은 대장기술과 기계공학 두 전문기술에 쓰이기 때문에 이 둘과 함께하면 정말 좋아요. 둘 중 하나를 올리고 싶다면 제 Forever 대장기술 숙련도 가이드나 Forever 기계공학 숙련도 가이드를 확인해 보세요.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever에는 새로운 광석, 주괴, 제조법이 몇 가지 추가되었어요. 여기에서 확인할 수 있어요:",
  ["Mining Trainer Locations"] = "채광 전문기술 상급자 위치",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "다르나서스를 제외한 모든 수도에 채광 전문기술 상급자가 있어요. 경비병에게 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["{b}Capital cities:{/b}"] = "{b}수도:{/b}",
  ["Orgrimmar: {n:0:horde:Makaru}"] = "오그리마: {n:0:horde:Makaru}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "언더시티: {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "썬더 블러프: {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}시작 지역:{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "시험의 골짜기의 {n:0:horde:Norzsh}(75까지만) 칼바위 언덕의 {n:0:horde:Krunn}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "나라체 야영지의 {n:0:horde:Vartha Rockmane}(75까지만) 썬더 블러프의 {n:0:horde:Brek Stonehoof}",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "데스넬의 {n:0:horde:Walter Mason}(75까지만) 언더시티의 {n:0:horde:Brom Killian}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "시작 지점인 Thendal Village에는 전문기술 상급자가 없지만 필요하지 않아요. {q:93552::Harvesting Windstones}는 Thendal Village에서 받는 첫 퀘스트 중 하나예요. 보상으로 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}를 고르면 채광을 배울 수 있어요. 섬의 전문기술 상급자는 Valanaar의 {n:0::Halavuul Cragwind}와 Shen'dar Village의 {n:0::Messana Crestwind}예요.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "스톰윈드: {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "아이언포지: {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "다르나서스: 전문기술 상급자가 없어요. 가장 가까운 상급자는 어둠해안 아우버다인의 {n:0:alliance:Kurdram Stonehammer}예요",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo}(75까지만) 스톰윈드의 {n:0:alliance:Gelman Stonehand}",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench}(75까지만) 스틸그릴 정비소의 {n:0:alliance:Yarr Hammerstone} 골볼라 채석장의 {n:0:alliance:Dank Drizzlecut}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "그늘 협곡 알드랏실의 {n:0:alliance:Fanorran Stilloak}(75까지만) 어둠해안 아우버다인의 {n:0:alliance:Kurdram Stonehammer}",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "호드와 얼라이언스의 모든 채광 전문기술 상급자는 제 WoW Forever 채광 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Track Ore on Your Minimap"] = "미니맵에 광석 추적하기",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "한 번에 하나만 추적할 수 있어서 {b}광물과 약초를 함께 추적할 수는 없어요{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "{s:2580:spell_nature_earthquake:Find Minerals}는 채광과 함께 배우지만 기본적으로 켜져 있지 않아요:",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "화면 아래 메뉴의 두 번째 버튼인 망치와 곡괭이 버튼으로 전문기술 창을 여세요.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "채광 칸에서 광물 찾기를 클릭하세요. {b}죽은 후에 쓰는 버프 근처의 행동 단축바로 끌어다 놓는 것을 추천해요.{/b} 이렇게 하면 습관이 되어 잊어버릴 일이 줄어요.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "광물 찾기 버프는 미니맵 옆에 표시돼요. {b}죽을 때마다 추적이 꺼지니 다시 켜는 것을 잊지 마세요!{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "WoW Forever 전문기술 창의 광물 찾기 버튼",
  ["Mining Skill Bonuses"] = "채광 숙련도 보너스",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "꼭 필요하지는 않지만 두 광석 사이에서 막혔을 때 도움이 돼요. +5가 있으면 철 광맥을 125 대신 120부터 캘 수 있어서 주석의 느린 마지막 몇 포인트를 건너뛸 수 있어요.",
  ["Item"] = "아이템",
  ["Mining"] = "채광",
  ["How to get it"] = "얻는 방법",
  ["An enchanter"] = "마법부여사",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "기계공학자가 만들며, 착용하려면 기계공학 205가 필요해요",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Riverglades의 얼라이언스 퀘스트 A Miner Problem의 보상",
  ["Drops from Miner Johnson in The Deadmines"] = "죽음의 폐광의 광부 존슨이 드롭",
  ["Smelting to 105"] = "105까지 제련하기",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "경매장에서 광석을 사서 제련하면 처음 105 숙련도를 건너뛸 수 있어요. 평범하게 채광으로 올리고 싶다면 아래 채광 경로로 내려가세요. 하지만 골드가 있다면 시간을 많이 아낄 수 있어서 제련을 추천해요. 주괴가 광석보다 비싸게 팔리거나 가격이 거의 비슷할 때도 있어서 이렇게 해도 크게 손해 보지 않아요.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "{i:2770:inv_ore_copper_01:Copper Ore} 약 140개와 {i:2771:inv_ore_tin_01:Tin Ore} 약 70개를 사세요. 제련은 대부분 노란색과 녹색이라 운이 나쁘면 조금 더 필요할 수 있어요.",
  ["Notes"] = "메모",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "65가 될 때까지 120-140x {s:2657:inv_ingot_02:Smelt Copper}. 구리 주괴 70개는 청동에 필요하니 보관하세요.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "전문기술 상급자에게서 숙련 채광, 주석 제련, 청동 제련을 배우세요. 70x {s:3304:inv_ingot_05:Smelt Tin}을 하세요. 75에서 회색이 되지만 어차피 청동에 주석 주괴 70개가 모두 필요해요.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "만든 구리 주괴와 주석 주괴로 70x {s:2659:inv_ingot_bronze:Smelt Bronze}를 하세요. 100에서 110 사이가 될 테니 조금 더 필요할 수도 있어요.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "전문기술 상급자에게서 은 제련을 배우세요. 이 부분은 비용이 많이 들 수 있으니 먼저 은 광석과 은 주괴 가격을 확인하세요. 비용이 괜찮다면 120이 될 때까지 35-45x {s:2658:inv_ingot_01:Smelt Silver}를 하세요. 125까지 마지막 5포인트에는 은 광석이 약 50개 더 들 수 있으니 120부터는 채광을 추천해요(골드가 있다면 계속 제련해도 돼요). 철 광맥은 채광 125가 필요하지만 위의 채광 숙련도 보너스로 +5가 있으면 120부터 캘 수 있어서 주석을 건너뛰고 바로 철로 갈 수 있어요.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "전문기술 상급자 근처의 채광 용품 상인이나 상급자에게서 {i:2901:inv_pick_02:Mining Pick}를 {b}사는 것을 잊지 마세요{/b}!",
  ["You can buy one from these vendors:"] = "아래 상인들에게서 살 수 있어요:",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "시험의 골짜기의 {n:0:horde:Norzsh}, 칼바위 언덕의 {n:0:horde:Flakk}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "나라체 야영지의 {n:0:horde:Vartha Rockmane}, 블러드후프 마을의 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "데스넬의 {n:0:horde:Walter Mason}, 브릴의 {n:0:horde:Abigail Shiel}",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "Thendal Village의 {n:0::Uualia Suncrest}, Shen'dar Village의 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "명예의 계곡의 {n:0:horde:Gorina}",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "도적 지구의 {n:0:horde:Elizabeth Van Talen}",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "북녘골의 {n:0:alliance:Brother Danil}, 골드샤이어의 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "카라노스의 {n:0:alliance:Thrawn Boltar}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "그늘 협곡 알드랏실의 {n:0:alliance:Fanorran Stilloak}, 돌라나르의 {n:0:alliance:Narret Shadowgrove}",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "드워프 지구의 {n:0:alliance:Brooke Stonebraid}",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "거대한 용광로의 {n:0:alliance:Thurgrum Deepforge}",
  ["Darnassus"] = "다르나서스",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "위에서 말했듯이, 대부분의 고레벨 플레이어는 이 부분을 건너뛰고 최소 105까지 제련으로 올리는 것이 가장 좋다고 생각해요. 하지만 채광을 선호하고 지역을 고를 수 있다면 호드는 {b}듀로타{/b}, 얼라이언스는 {b}엘윈 숲{/b}이 가장 좋다고 생각해요.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "지역을 한두 바퀴 돌면 제련으로 65까지 올릴 만큼 구리 광석을 얻을 수 있어요.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "한 바퀴를 돈 후 {b}칼바위 언덕에 들러 구리 광석을 구리 주괴로 제련하세요{/b}.",
  ["Mining route in Durotar"] = "듀로타 채광 경로",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "빨간 원으로 표시한 동굴 안에는 구리 광맥이 5개 있어요. {b}재생성 속도가 아주 빨라서 사실상 동굴 안에만 있어도 숙련도를 올릴 수 있어요{/b}. 동굴 구조도 아주 좋아요. 끝에 뛰어내릴 곳이 있어서 빠르게 처음으로 돌아가 계속 캘 수 있어요. 재생성 속도가 부족하거나 경쟁자가 있다면 밖으로 나가서 구리 광맥 몇 개를 캐고 다시 동굴로 돌아오세요.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "멀고어를 한 바퀴 도는 것도 좋아요. 경로가 아주 따라가기 쉬운데, 기본적으로 지역 가장자리를 도는 순환 경로예요. 하지만 탈것이 없을 때는 동굴이 더 나았어요.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}바엘던 발굴현장에서 광석을 제련할 수 있어요{/b}. 동굴 바로 북쪽의 드워프 야영지에 용광로와 모루가 있어요(지도에 표시됨). 그곳의 드워프들은 적대적이에요.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "바엘던 발굴현장의 용광로와 모루가 표시된 멀고어 채광 경로",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "두 경로 모두 좋아요. 지역 동쪽 경로는 퀘스트 거점이 적어서 사람이 더 적을 거예요.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "한 바퀴를 돈 후 {b}브릴에 들러{/b} 구리 광석을 제련하세요.",
  ["Mining route in Tirisfal Glades"] = "티리스팔 숲 채광 경로",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones}는 Thendal Village에서 받는 첫 퀘스트 중 하나예요. 보상으로 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}를 고르면 채광을 배울 수 있어요.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "이 지역은 재생성 속도가 아주 빨라서 가끔은 광맥이 제 바로 위에 생기기도 했어요. 더 큰 경로를 돌아도 되지만, 탈것이 없고 재생성이 빨라서 그럴 필요가 없었어요.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "한 바퀴를 돈 후 {b}Shen'dar Village에 들러{/b} 구리 광석을 제련하세요.",
  ["Mining route on Zephras Isle"] = "Zephras Isle 채광 경로",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "표시된 경로를 따라 왔다 갔다 하고, 레벨이 충분하다면 동굴도 정리하세요. 동굴 안은 재생성 속도가 꽤 빨라서 레벨에 따라서는 동굴을 나올 필요도 없을 거예요. 동굴을 건너뛰어도 돼요. 경로의 재생성 속도도 충분히 빠른 것 같지만, 그렇다면 북쪽으로 살짝 돌아가는 길도 들르세요.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "한 바퀴를 돈 후 {b}골드샤이어에 들러{/b} 구리 광석을 제련하세요.",
  ["Mining route in Elwynn Forest"] = "엘윈 숲 채광 경로",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "특별히 할 말은 없어요. 이 지역을 빙빙 돌기만 하면 돼요. 동굴은 선택 사항이라 들어가지 않아도 되고, 밖의 재생성 속도도 꽤 빨라요.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "한 바퀴를 돈 후 {b}카라노스에 들러{/b} 구리 광석을 제련하세요.",
  ["Mining route in Dun Morogh"] = "던 모로 채광 경로",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "이 두 동굴은 재생성 속도가 엄청나게 빨라요. 계속 이럴지는 모르겠지만, 지금은 동굴 안에만 있어도 숙련도를 올릴 수 있어요.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "텔드랏실에는 용광로가 없어요. {b}가장 가까운 곳은 다르나서스 전사의 정원이에요{/b}.",
  ["Mining route in Teldrassil"] = "텔드랏실 채광 경로",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "전문기술 상급자에게 가서 숙련 채광을 배우세요. 채광 50이 필요해요. 시작 지역의 새로운 초급 채광 전문기술 상급자는 숙련 채광을 가르쳐 주지 않아요.",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "이 시점에 구리 광석이나 주석 광석이 있다면 떠나기 전에 제련해서 청동 주괴를 만드세요. 청동은 105 즈음부터 숙련도가 오르지 않아요.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "얼라이언스는 동굴을 감당할 수 있다면 {b}저습지{/b}가 단연 최고예요. 호드는 {b}은빛소나무 숲{/b} 동굴이나 {b}힐스브래드 구릉지{/b}가 좋아요. 나머지는 비슷비슷해서 판단하기 어려워요.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "이 지역의 광석: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "주석 광맥은 채광 65, 은 광맥은 75가 필요해요.",
  ["Wetlands"] = "저습지",
  ["Silverpine Forest"] = "은빛소나무 숲",
  ["Westfall"] = "서부 몰락지대",
  ["Hillsbrad Foothills"] = "힐스브래드 구릉지",
  ["The Barrens"] = "불모의 땅",
  ["Ashenvale"] = "잿빛 골짜기",
  ["Stonetalon Mountains"] = "돌발톱 산맥",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "저습지의 이 동굴은 얼라이언스 플레이어가 채광을 올리기에 가장 좋은 곳이에요. 동굴 안에는 주석 광맥과 발화석 광맥이 가득하고 재생성 시간이 아주 빨라요.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "몹은 레벨 20 정도이고 {b}Forever에서는 훨씬 빨리 재생성되기 때문에 레벨이 꽤 많이 높아야 해요{/b}. 그렇지 않으면 계속 바로 옆에서 다시 나타날 거예요.",
  ["Mining route in the Wetlands"] = "저습지 채광 경로",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "이 동굴에는 광맥 생성 지점이 3개 있고 재생성 시간이 아주 빨라요. 광맥을 캐고 재생성을 기다리기만 하면 돼요(약 2분).",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "몹은 레벨 21-22 정도이고 {b}Forever에서는 훨씬 빨리 재생성되기 때문에 레벨이 꽤 많이 높아야 해요{/b}. 그렇지 않으면 계속 바로 옆에서 다시 나타날 거예요.",
  ["Mining route in Silverpine Forest"] = "은빛소나무 숲 채광 경로",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "이 동굴에는 아주 빨리 재생성되는 주석 광맥이 여러 개 있어요. 밖에도 광맥이 있으니 너무 빨리 다 캤다면 밖으로 나가서 몇 개 더 캐도 돼요.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "몹은 레벨 13-15 정도이고 {b}Forever에서는 훨씬 빨리 재생성되기 때문에 레벨이 꽤 많이 높아야 해요{/b}. 그렇지 않으면 계속 바로 옆에서 다시 나타날 거예요.",
  ["Mining route in Westfall"] = "서부 몰락지대 채광 경로",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "평범하게 채광하는 것을 선호한다면 여기가 가장 좋지만, 인기 있는 지역이라 다른 플레이어와 경쟁이 더 심할 수 있어요. 경로가 호드 마을 주변을 지나기 때문에 얼라이언스는 어떨지 잘 모르겠어요. 아마 경비병을 피할 수 있을 것 같지만, 호드 캐릭터로만 테스트했어요.",
  ["Mining route in Hillsbrad Foothills"] = "힐스브래드 구릉지 채광 경로",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "이곳 몹은 레벨 22-26 정도라서 그보다 레벨이 높을 때 오는 것이 가장 좋아요. 그래도 재생성 속도는 빨라요.",
  ["Mining route in The Barrens"] = "불모의 땅 채광 경로",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "따라가기 쉬운 아주 단순한 경로예요. 평범하게 채광하는 것을 선호한다면 여기가 가장 좋지만, 인기 있는 지역이라 다른 플레이어와 경쟁이 더 심할 수 있어요.",
  ["Mining route in Ashenvale"] = "잿빛 골짜기 채광 경로",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "제가 테스트할 때는 주변에 사람이 거의 없었기 때문에, 여러 명이 채광을 올리고 있다면 이 경로는 잘 안 될 수도 있어요. 하지만 이곳은 보통 사람이 적어서 동굴에서 올리고 싶지 않다면 좋은 대안이라고 생각해요. 유일한 단점은 가끔 주석 광맥 대신 철 광맥이 생겨서 아직 캘 수 없다는 거예요.",
  ["Mining route in Stonetalon Mountains"] = "돌발톱 산맥 채광 경로",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "여기부터는 일반적인 클래식 채광 경로를 따라요. 베타 레벨 제한이 30이라 아라시와 잊혀진 땅은 제대로 테스트하지 못했어요. 라이브에서 캐릭터 레벨을 더 올리면 이 부분을 수정할 텐데, 주된 변경점은 광석 재생성 속도라서 대부분의 경로가 통할 거고 대부분의 지역에서 더 짧은 경로를 돌아도 될 거예요.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}전문기술 상급자에게 가서 전문 채광을 배우세요{/b}. 채광 125가 필요해요.",
  ["Smelting Iron and Gold (optional)"] = "철과 금 제련하기 (선택)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "시간을 아끼고 싶고 골드가 있다면 채광하러 가기 전에 {i:2772:inv_ore_iron_01:Iron Ore} 약 20개를 사서 135까지 {s:3307:inv_ingot_iron:Smelt Iron}을 하세요. 135 이후에는 숙련도가 거의 오르지 않으니 140까지 오를 거라고 기대하지 마세요.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "155가 되면 전문기술 상급자에게서 {s:3308:inv_ingot_03:Smelt Gold}를 배울 수 있어요. 170까지는 매번 숙련도가 오르기 때문에 금 광석 약 22개면 155에서 175까지 올라서 바로 미스릴을 시작할 수 있어요. 먼저 금 광석과 금 주괴 가격을 확인하는 것을 추천해요.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "레벨 30 정도의 {b}저레벨 캐릭터{/b}라면 가장 안전한 {b}버섯구름 봉우리{/b} 경로를 따르세요. 이미 {b}고레벨 캐릭터이거나 탈것이 있다면{/b} {b}아라시 고원{/b}을 추천해요.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "이 지역의 광석: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "철 광맥은 채광 125, 금 광맥은 155가 필요해요.",
  ["Arathi Highlands"] = "아라시 고원",
  ["Thousand Needles"] = "버섯구름 봉우리",
  ["Desolace"] = "잊혀진 땅",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "지도에 빨간 원으로 표시한 동굴이 4개 있어요. 입구에서는 모든 광맥이 보이지 않으니 각 동굴의 끝까지 꼭 들어가세요.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "저레벨 플레이어는 동굴 4개를 모두 건너뛰고, 저레벨 얼라이언스 플레이어는 해머폴 남쪽으로 돌아가세요!",
  ["Mining route in Arathi Highlands"] = "아라시 고원 채광 경로",
  ["Mining route in Thousand Needles"] = "버섯구름 봉우리 채광 경로",
  ["Mining route in Desolace"] = "잊혀진 땅 채광 경로",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "225 이상을 배우려면 전문기술 상급자에게 가서 장인 채광을 배우세요. 채광 200이 필요해요.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "이 지역의 광석: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "미스릴 광맥은 채광 175, 진은 광맥은 230이 필요해요.",
  ["The Hinterlands"] = "동부 내륙지",
  ["Tanaris"] = "타나리스",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "빨간 경로는 레벨 62 정예 몹이 가득하니 저레벨 플레이어는 건너뛰세요. 저레벨 플레이어는 지도에 빨간 원으로 표시한 동굴도 건너뛰는 것을 고려해 보세요(장비/직업에 따라 달라요).",
  ["Mining route in The Hinterlands"] = "동부 내륙지 채광 경로",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "레벨 60 미만 플레이어는 빨간 원으로 표시한 동굴 4개를 건너뛰세요.",
  ["Mining route in Tanaris"] = "타나리스 채광 경로",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "이 지역의 광석: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "작은 토륨 광맥은 채광 245가 필요해요.",
  ["Un'Goro Crater"] = "운고로 분화구",
  ["Blasted Lands"] = "저주받은 땅",
  ["Felwood"] = "악령의 숲",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "지도에 빨간 원으로 표시한 두 동굴에서 광맥 2-3개를 찾을 수 있어요.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "저레벨 플레이어는 남쪽 동굴을 건너뛰는 것이 좋을 거예요. 레벨, 장비, 직업에 따라 정말 달라요.",
  ["Mining route in Un'Goro Crater"] = "운고로 분화구 채광 경로",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "빨간 원으로 표시한 두 동굴 모두 안에 몹이 많아서, 이 지역은 좋은 장비를 갖춘 레벨 60 플레이어나 은신이 있는 드루이드와 도적에게만 추천해요.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "주둔지 무기고 광산 안은 길 찾기가 정말 어려워서 작은 지도를 넣었어요. {b}얼라이언스{/b} 플레이어는 주둔지 무기고 안에서 채광할 수 없어요!",
  ["Mining route in the Blasted Lands"] = "저주받은 땅 채광 경로",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "빨간 원으로 표시한 동굴 안에는 보통 광맥이 2개 있어요. 동굴이 작고 안에 몹도 많지 않아서 들어갈 가치가 있고, 레벨이 높다면 일부는 어그로 없이 지나갈 수 있어요.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "제데나르의 다른 두 동굴, 특히 어둠의 요새는 건너뛰는 것을 추천해요(은신이 있다면 들어갈 가치가 있을 수도 있어요).",
  ["Mining route in Felwood"] = "악령의 숲 채광 경로",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "이 지역의 광석: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "275가 되면 풍부한 토륨 광맥도 캘 수 있어요.",
  ["Eastern Plaguelands"] = "동부 역병지대",
  ["Winterspring"] = "여명의 설원",
  ["Burning Steppes"] = "불타는 평원",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "앞의 운고로 경로와 거의 같지만, 이제 풍부한 토륨 광맥이 포함돼요.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "풍부한 토륨 광맥이 포함된 운고로 분화구 채광 경로",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "빨간 선에는 레벨 57-58 정예 몹이 가득해서, 장비가 좋지 않다면 은신이 없는 한 그 부분은 건너뛰는 것이 좋아요. 조금 연습하면 보통 몇 마리만 끌고 지나갈 수 있어요.",
  ["Mining route in the Eastern Plaguelands"] = "동부 역병지대 채광 경로",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "이 동굴의 몹은 그렇게 어렵지 않아서 대부분의 직업이 정리할 수 있어요(장비에 따라 달라요).",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "대부분의 직업은 최소한 동굴의 첫 부분까지는 어그로 없이 들어갈 수 있어요. 장비에 따라 더 깊이 들어가 보세요.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "이 협곡에는 정예 몹이 많이 순찰하지만, 보통 대부분 어그로 없이 지나갈 수 있어요. 가끔 1-2마리는 처치해야 해요.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "죽지 않고 이곳에서 채광하기 어려워서 대부분의 플레이어에게는 추천하지 않아요. 직업과 몹을 피하는 실력에 따라 정말 달라요.",
  ["Mining route in Winterspring"] = "여명의 설원 채광 경로",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "빨간 원으로 표시한 두 동굴에는 레벨 50 몹이 가득해서 저레벨 플레이어는 건너뛰는 것이 좋을 수 있어요(장비와 레벨에 따라 달라요).",
  ["Mining route in the Burning Steppes"] = "불타는 평원 채광 경로",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "이 WoW Forever 약초채집 숙련도 가이드는 약초채집 숙련도를 1에서 300까지 가장 빠르게 올리는 방법을 알려드려요. 지역별 경로 지도, 모든 전문기술 상급자의 위치와 75, 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "아래에서 시작 지역과 수도별 약초채집 전문기술 상급자, 그리고 숙련도 구간별로 약초를 캐기 가장 좋은 지역을 확인할 수 있어요. 약초채집은 캔 약초로 물약과 비약을 만들 수 있어서 연금술과 잘 어울려요. 연금술을 올리고 싶다면 제 Forever 연금술 숙련도 가이드를 확인해 보세요. 다만 이 가이드는 약초채집을 최대한 빨리 올리기 위한 것이라, 캐는 약초가 연금술에 가장 좋은 것은 아닐 때도 있어요.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever에는 새로운 약초, 씨앗, 제조법이 몇 가지 추가되었어요. 여기에서 확인할 수 있어요:",
  ["Herbalism Trainer Locations"] = "약초채집 전문기술 상급자 위치",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "모든 수도에 약초채집 전문기술 상급자가 있어요. 경비병에게 약초채집가가 어디 있는지 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["Orgrimmar: {n:0:horde:Jandi}"] = "오그리마: {n:0:horde:Jandi}",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "언더시티: {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "썬더 블러프: {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "시험의 골짜기의 {n:0:horde:Zor'la}(75까지만) 센진 마을의 {n:0:horde:Mishiki}",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "나라체 야영지의 {n:0:horde:Garan Sunstrider}(75까지만) 썬더 블러프의 {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "데스넬의 {n:0:horde:Florence Nightshade}(75까지만) 브릴의 {n:0:horde:Faruza}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "시작 지점인 Thendal Village에는 전문기술 상급자가 없지만 필요하지 않아요. {q:93552::Harvesting Windstones}는 Thendal Village에서 받는 첫 퀘스트 중 하나예요. 보상으로 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}를 고르면 약초채집을 배울 수 있어요. 섬의 전문기술 상급자는 Valanaar의 {n:0::Syriel Nightrain}과 Shen'dar Village의 {n:0::Halassa Fernbreeze}예요.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "스톰윈드: {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "아이언포지: {n:0:alliance:Reyna Stonebranch}",
  ["Darnassus: {n:0:alliance:Firodren Mooncaller}"] = "다르나서스: {n:0:alliance:Firodren Mooncaller}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower}(75까지만) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard}(75까지만) 아이언포지의 {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "그늘 협곡 알드랏실의 {n:0:alliance:Eleyna Duskbreeze}(75까지만) 돌라나르의 {n:0:alliance:Malorne Bladeleaf}",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "호드와 얼라이언스의 모든 약초채집 전문기술 상급자는 제 WoW Forever 약초채집 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Track Herbs on Your Minimap"] = "미니맵에 약초 추적하기",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "한 번에 하나만 추적할 수 있어서 {b}약초와 광물을 함께 추적할 수는 없어요{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "{s:2383:inv_misc_flower_02:Find Herbs}는 약초채집과 함께 배우지만 기본적으로 켜져 있지 않아요:",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "약초채집 칸에서 약초 찾기를 클릭하세요. {b}죽은 후에 쓰는 버프 근처의 행동 단축바로 끌어다 놓는 것을 추천해요.{/b} 이렇게 하면 습관이 되어 잊어버릴 일이 줄어요.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "약초 찾기 버프는 미니맵 옆에 표시돼요. {b}죽을 때마다 추적이 꺼지니 다시 켜는 것을 잊지 마세요!{/b}",
  ["Herbalism Skill Bonuses"] = "약초채집 숙련도 보너스",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "꼭 필요하지는 않지만 두 약초 사이에서 막혔을 때 도움이 돼요. +5가 있으면 왕꽃잎풀을 125 대신 120부터 캘 수 있어서 더 일찍 넘어갈 수 있어요.",
  ["Herbalism"] = "약초채집",
  ["A world drop, check the Auction House"] = "필드 드롭이에요. 경매장을 확인하세요",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "가시덩굴 구릉의 헨리 스턴이 제조법을 가르쳐 주며, {b}요리 175가 필요해요{/b}. 던전 입구에서 왼쪽 길로 끝까지 가서 마구간에 도착하면 벽을 부수고 그에게 말을 거세요.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "아직 캘 수 없는 약초를 발견했는데 몇 포인트만 모자랄 때 아주 유용해요. 초반에는 황금가시 가격 때문에 꽤 비쌀 수 있지만, 약초채집을 올리는 동안 몇 개 가지고 다닐 가치가 있어요.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "모든 시작 지역에 약초가 가득해서 어디를 골라도 크게 상관없어요. 재생성 속도가 너무 빨라서 탈것이 없으면 한 바퀴를 다 돌지도 못할 때가 많고, 그냥 빙빙 돌면서 보이는 약초를 캐면 돼요.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "이 지역의 약초: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "뱀뿌리는 약초채집 15가 필요해요.",
  ["Herbalism route in Durotar"] = "듀로타 약초채집 경로",
  ["Herbalism route in Mulgore"] = "멀고어 약초채집 경로",
  ["Herbalism route in Tirisfal Glades"] = "티리스팔 숲 약초채집 경로",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones}는 Thendal Village에서 받는 첫 퀘스트 중 하나예요. 보상으로 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}를 고르면 약초채집을 배울 수 있어요.",
  ["Herbalism route on Zephras Isle"] = "Zephras Isle 약초채집 경로",
  ["Herbalism route in Elwynn Forest"] = "엘윈 숲 약초채집 경로",
  ["Herbalism route in Dun Morogh"] = "던 모로 약초채집 경로",
  ["Herbalism route in Teldrassil"] = "텔드랏실 약초채집 경로",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "전문기술 상급자에게 가서 숙련 약초채집을 배우세요. 약초채집 50이 필요해요. 시작 지역의 새로운 초급 약초채집 전문기술 상급자는 숙련 약초채집을 가르쳐 주지 않아요.",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "이 지역의 약초: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "갈래물풀은 약초채집 85가 필요해서 바로 캘 수는 없어요.",
  ["Loch Modan"] = "모단 호수",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "은빛소나무 숲 아래쪽은 재생성 속도가 충분히 빨라서 표시된 구역에서 작은 원을 그리며 돌기만 하면 돼요. 탈것 없이 테스트했기 때문에 탈것이 있으면 다를 수 있지만, 그럴 때는 큰길을 따라 순환 경로까지 오르내려도 잘 될 거예요.",
  ["Herbalism route in Silverpine Forest"] = "은빛소나무 숲 약초채집 경로",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "아주 따라가기 쉬운 경로지만 어둠해안보다는 약초가 조금 적을 수 있어요.",
  ["Herbalism route in Loch Modan"] = "모단 호수 약초채집 경로",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "어둠해안은 어디에나 약초가 있어요. 저는 이 순환 경로를 썼지만 지도 위쪽까지 넓혀도 돼요. 재생성 속도가 빨라서 여러 구역에서 작은 원을 그리며 돌아도 돼요. 저는 이 경로가 꽤 쉽고 편하게 따라갈 수 있었어요.",
  ["Herbalism route in Darkshore"] = "어둠해안 약초채집 경로",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "150 이상을 배우려면 전문기술 상급자에게 가서 전문 약초채집을 배우세요. 약초채집 125가 필요해요.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "이 지역의 약초: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "왕꽃잎풀은 약초채집 125, 생명의 뿌리는 150이 필요해서 바로 캘 수는 없어요.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "힐스브래드 구릉지에서 이 순환 경로를 돌면 약초가 재생성될 시간이 충분하지만, 탈것 없이 테스트했기 때문에 탈것이 있으면 다를 수 있어요.",
  ["Herbalism route in Hillsbrad Foothills"] = "힐스브래드 구릉지 약초채집 경로",
  ["All three areas are good here:"] = "여기는 세 구역 모두 좋아요:",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "이곳 몹은 레벨 14-15 정도밖에 안 돼서 이 약초들을 안전하게 캘 수 있는 가장 낮은 레벨의 구역이에요.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "누군가 이미 첫 번째 구역에서 캐고 있다면 좋은 대안이에요. 이곳 몹은 레벨 25 정도로 더 높아요.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "이 구역은 보통 꽤 붐비고 몹도 많아요. 여기에는 왕꽃잎풀이 더 많기 때문에 {b}이미 125를 넘었을 때만 추천해요{/b}.",
  ["Herbalism route in Stonetalon Mountains"] = "돌발톱 산맥 약초채집 경로",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "여기부터는 일반적인 클래식 약초채집 경로를 따라요. 베타 레벨 제한이 30이라 고레벨 경로는 테스트하지 못했어요. 라이브에서 캐릭터 레벨을 더 올리면 이 부분을 수정할 텐데, 주된 변경점은 약초 재생성 속도라서 대부분의 경로가 통할 거예요.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "이 지역의 약초: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "카드가의 수염은 약초채집 185가 필요해서 바로 캘 수는 없어요.",
  ["Stranglethorn Vale"] = "가시덤불 골짜기",
  ["Herbalism route in Stranglethorn Vale"] = "가시덤불 골짜기 약초채집 경로",
  ["Herbalism route in Arathi Highlands"] = "아라시 고원 약초채집 경로",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}이 지역으로 떠나기 전에 장인 약초채집을 배우세요{/b}. 약초채집 200이 필요해요. 타나리스와 이글거리는 협곡에는 전문기술 상급자가 없어서, 건너뛰면 225에서 다시 날아가야 해요.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "이 지역의 약초: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "이글거리는 협곡",
  ["Herbalism route in Tanaris"] = "타나리스 약초채집 경로",
  ["Herbalism route in Searing Gorge"] = "이글거리는 협곡 약초채집 경로",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "동부 내륙지의 약초: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "빨간 X로 동굴을 표시했어요. 동굴 안에 유령버섯이 많지만 약초채집 245가 있어야 캘 수 있어요.",
  ["Herbalism route in The Hinterlands"] = "동부 내륙지 약초채집 경로",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "악령의 숲의 약초: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "악령의 숲 약초채집 경로",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "이 WoW Forever 무두질 숙련도 가이드는 무두질 숙련도를 1에서 300까지 가장 빠르게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 숙련도 구간별로 무두질하기 가장 좋은 곳도 확인할 수 있어요.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "이 가이드는 전문기술을 바꾸려는 고레벨 플레이어를 위한 것이지만 저레벨 플레이어에게도 좋아요. 무두질은 올리기 쉽지만 정말 지루해요. 돌아다니면서 수백 마리의 몹을 무두질해야 하거든요. 무두질한 가죽을 쓸 수 있어서 가죽세공과 잘 어울리니, 가죽세공을 올리고 싶다면 제 Forever 가죽세공 숙련도 가이드를 확인해 보세요.",
  ["Skinning Trainer Locations"] = "무두질 전문기술 상급자 위치",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "모든 수도에 무두질 전문기술 상급자가 있어요. 경비병에게 물어보면 지도에 빨간 깃발로 표시돼요.",
  ["Orgrimmar: {n:0:horde:Thuwd}"] = "오그리마: {n:0:horde:Thuwd}",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "언더시티: {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "썬더 블러프: {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "시험의 골짜기의 {n:0:horde:Kagil}(75까지만) 오그리마의 {n:0:horde:Thuwd}",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "나라체 야영지의 {n:0:horde:Nawka Wildsong}(75까지만) 블러드후프 마을의 {n:0:horde:Yonn Deepcut}",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "데스넬의 {n:0:horde:Margaret Weaver}(75까지만) 티리스팔 숲의 {n:0:horde:Rand Rhobart}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "시작 지점인 Thendal Village에는 전문기술 상급자가 없지만 필요하지 않아요. {q:93552::Harvesting Windstones}는 Thendal Village에서 받는 첫 퀘스트 중 하나예요. 보상으로 {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners}를 고르면 무두질을 배울 수 있어요. 섬의 전문기술 상급자는 Valanaar의 {n:0::Ishlee Breezewhisper}와 Shen'dar Village의 {n:0::Mendalass Tattermend}예요.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "스톰윈드: {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "아이언포지: {n:0:alliance:Balthus Stoneflayer}",
  ["Darnassus: {n:0:alliance:Eladriel}"] = "다르나서스: {n:0:alliance:Eladriel}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "북녘골의 {n:0:alliance:Riley Peltskinner}(75까지만) 골드샤이어의 {n:0:alliance:Helene Peltskinner}",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer}(75까지만) 아이언포지의 {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "그늘 협곡 알드랏실의 {n:0:alliance:Terunne Bearshaper}(75까지만) 텔드랏실의 {n:0:alliance:Radnaal Maneweaver}",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "호드와 얼라이언스의 모든 무두질 전문기술 상급자는 제 WoW Forever 무두질 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Skinning Skill Requirements"] = "무두질 숙련도 요구 사항",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "몹을 무두질하려면 몹 레벨의 5배만큼 무두질 숙련도가 필요해요. 그래서 레벨 30 몹은 무두질 150이 필요해요. 레벨 20 미만은 더 적게 필요한데, 가이드를 따르면 신경 쓰지 않아도 돼요.",
  ["Mob level"] = "몹 레벨",
  ["Skinning needed"] = "필요한 무두질",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "레벨 11 몹은 10, 레벨마다 10씩 증가 (레벨 15는 50, 레벨 19는 90 필요)",
  ["20 and up"] = "20 이상",
  ["5 times the level"] = "레벨의 5배",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "장갑에 {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}을 마법부여하면 평소보다 1레벨 높은 몹을 무두질할 수 있어요.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "호드 플레이어는 불모의 땅의 Unwelcome Guests 보상으로 {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife}(무두질 +3)를 고를 수도 있어요.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "WoW Forever에서는 시작 지역의 몹도 무두질할 수 있고, 75까지 숙련도가 올라요.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "여기에는 {b}어느 시작 지역이든 좋아요{/b}. 새 캐릭터를 키운다면 시작 지역의 아무 몹이나 무두질할 수 있으니, 지역을 떠나는 레벨 10 정도까지는 추천이 필요 없어요. 아래 두 곳은 이미 고레벨 캐릭터가 있고 무두질을 따라잡고 싶은 플레이어를 위한 곳이에요. 많은 플레이어가 그곳에서 새 캐릭터를 키우고 있어서 무두질할 몹이 항상 있어요.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}{i:7005:inv_weapon_shortblade_01:Skinning Knife}를 사는 것을 잊지 마세요!{/b} 전문기술 상급자 근처의 가죽세공 용품 상인과 대부분의 잡화 상인이 팔아요. 장착할 필요는 없지만 가방에 없으면 무두질할 수 없어요.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "듀로타 시험의 골짜기의 {n:3098::Mottled Boars}를 무두질하세요.",
  ["{b}Mob level:{/b} 1-2"] = "{b}몹 레벨:{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "듀로타 시험의 골짜기의 얼룩무늬 멧돼지",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "엘윈 숲 북녘골의 {n:299::Young Wolves}와 {n:69::Timber Wolves}를 무두질하세요.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "엘윈 숲 북녘골의 늑대들",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "아직 배우지 않았다면 전문기술 상급자에게 가서 숙련 무두질을 배우세요. 무두질 50이 필요해요. 시작 지역의 새로운 초급 무두질 전문기술 상급자는 숙련 무두질을 가르쳐 주지 않아요.",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "150 이상을 배우려면 125가 되었을 때 전문기술 상급자에게 다시 가서 전문 무두질을 배우세요.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "{n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}를 처치하고 무두질하세요.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "북부 감시 요새 바로 서쪽의 작은 랩터 야영지로 가세요. 80까지는 레벨 16-17 랩터를 무두질하고, 80부터는 레벨 18도 무두질할 수 있어요. 150까지 여기 있으세요. 마지막 10포인트는 녹색이지만 재생성이 빨라요.",
  ["{b}Mob level:{/b} 16-18"] = "{b}몹 레벨:{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "불모의 땅 북부 감시 요새 서쪽의 태양비늘 낫발톱",
  ["75-125 Loch Modan"] = "75-125 모단 호수",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "{n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}를 처치하고 무두질하세요.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "{n:1693::Loch Crocolisk}도 무두질할 수 있으니 물가에 가면 꼭 끌어오세요.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "125 정도까지 여기 있다가 북쪽의 저습지로 가세요. 힐스브래드로 가는 길에 있어요.",
  ["{b}Mob level:{/b} 16-17"] = "{b}몹 레벨:{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "모단 호수 무두질 장소",
  ["125-150 Wetlands"] = "125-150 저습지",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "{n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}를 처치하고 무두질하세요.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "웰가르 발굴현장에는 항상 몇 마리씩 있어서 잡을 몹이 떨어질 일이 없어요.",
  ["{b}Mob level:{/b} 25-27"] = "{b}몹 레벨:{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "저습지의 웰가르 발굴현장",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "150부터는 알터랙 산맥 경계에 있는 예티 동굴인 힐스브래드 구릉지의 구릉지 동굴이나, 그늘숲의 썩어가는 과수원으로 가세요.",
  ["Duskwood"] = "그늘숲",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "두 진영 모두 갈 수 있어요. 호드는 타렌 밀농장에서, 얼라이언스는 사우스쇼어에서 가면 돼요.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "{n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}를 처치하고 무두질하세요.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "예티가 아주 빨리 재생성돼서 내내 동굴 안에 있어도 돼요.",
  ["{b}Mob level:{/b} 30-32"] = "{b}몹 레벨:{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "힐스브래드 구릉지의 구릉지 동굴",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "그늘숲은 얼라이언스 지역이지만 그롬골이 가까워서 호드 플레이어도 갈 수 있어요.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "{n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}를 처치하고 무두질하세요.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "1로 표시한 구역에서 시작해서 롤란드의 파멸 동굴 안팎의 몹을 정리한 다음, 몹이 재생성될 때까지 썩어가는 과수원으로 가세요.",
  ["{b}Mob level:{/b} 26-29"] = "{b}몹 레벨:{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "그늘숲의 롤란드의 파멸과 썩어가는 과수원",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "전문기술 상급자에게 가서 장인 무두질을 배우세요. 무두질 200이 필요해요.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "탈것을 타고 페랄라스 남쪽 야수발톱 골짜기의 예티 동굴로 가세요. 두 진영 모두 갈 수 있어요. 호드는 모자케 야영지에서, 얼라이언스는 페더문 요새에서 가면 돼요.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "{n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}를 처치하고 무두질하세요.",
  ["{b}Mob level:{/b} 43-46"] = "{b}몹 레벨:{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "페랄라스 야수발톱 골짜기의 예티 동굴",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "280부터는 마샬의 은신처로 날아가서 운고로 분화구 서쪽의 공룡을 무두질하세요.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "{n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}를 처치하고 무두질하세요.",
  ["{b}Mob level:{/b} 50-55"] = "{b}몹 레벨:{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "운고로 분화구 서쪽의 공룡 구역",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "이 WoW Forever 낚시 및 요리 숙련도 가이드는 낚시와 요리를 1에서 300까지 함께 가장 빠르게 올리는 방법을 알려드려요.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "낚시는 올리는 데 시간이 오래 걸려서 두 가지를 함께 올리는 것이 가장 좋아요. 잡는 물고기마다 요리 재료가 되어서 낚시하는 동안 요리 숙련도가 공짜로 오르거든요. 그래도 처음부터 끝까지 물고기를 아주 많이 잡아야 하니 인내심이 많이 필요해요. 하나만 올리고 싶다면 대신 제 낚시 가이드나 요리 가이드를 이용하세요.",
  ["Level Fishing to 75"] = "낚시 75까지 올리기",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "고를 수 있다면 {b}멀고어에서 낚시를 올리세요{/b}. 모든 것이 가까이 모여 있거든요. 블러드후프 마을의 {n:0::Harn Longcast}가 두 요리법과 낚싯대를 모두 팔고, 낚시 전문기술 상급자는 스톤불 호수에 있어요. 75 이후에 낚시할 썬더 블러프도 바로 옆이에요.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "아직 낚시를 배우지 않았다면 센진 마을 남쪽 해안의 {n:0::Lau'Tiki}에게서 배우세요.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "센진 마을의 {n:0::Zansoa}에게서 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}을 사세요. {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}도 거기서 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 센진 마을 남쪽 {n:0::Lau'Tiki} 옆 해안에서 낚시 숙련도가 75가 될 때까지 낚시하세요. 거기서 잡히는 것은 거의 다 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}이며, 약 70마리예요.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "{n:0::Lau'Tiki}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 듀로타 센진 마을 남쪽 해안",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "아직 낚시를 배우지 않았다면 스톤불 호수의 {n:0::Uthan Stillwater}에게서 배우세요.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "블러드후프 마을의 {n:0::Harn Longcast}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}와 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 사세요. {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}도 거기서 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 스톤불 호수에서 낚시 숙련도가 75가 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 45마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 30마리를 잡게 될 거예요.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "{n:0::Uthan Stillwater}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 멀고어 블러드후프 마을 주변의 스톤불 호수",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "아직 낚시를 배우지 않았다면 맑은물 호수의 {n:0::Clyde Kellen}에게서 배우세요.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "브릴 남동쪽 죽음의 감시 간이역의 {n:0::Martine Tramblay}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}를 사세요. {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}도 거기서 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 맑은물 호수에서 낚시 숙련도가 75가 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 30마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 20마리, 그리고 {i:6299:inv_misc_fish_28:Sickly Looking Fish}와 잡동사니를 좀 잡게 될 거예요.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "{n:0::Clyde Kellen}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 티리스팔 숲 브릴 동쪽의 맑은물 호수",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "아직 낚시를 배우지 않았다면 Shen'dar Village의 {n:0::Fenn Fairweather}나 Valanaar의 {n:0::Baelann Swiftcurrent}에게서 배우세요.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Shen'dar Village의 {n:0::Belandiel Farflight}나 Valanaar의 {n:0::Baelann Swiftcurrent}에게서 {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}을 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, Zephras Isle의 아무 호수나 강에서 낚시 숙련도가 75가 될 때까지 낚시하세요. 예를 들어 Shen'dar Village와 Valanaar의 낚시 전문기술 상급자 옆도 좋아요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 45마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 30마리를 잡게 될 거예요. 잡은 물고기는 모두 보관하세요.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "{n:0::Fenn Fairweather}나 {n:0::Baelann Swiftcurrent}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "썬더 블러프에 도착하면 {n:0::Sewa Mistrunner}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}를, {n:0::Naal Mistrunner}에게서 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 사세요. 둘은 나란히 서 있어요.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, Zephras Isle의 Shen'dar Village와 Valanaar의 물가",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "고를 수 있다면 {b}엘윈 숲에서 낚시를 올리세요{/b}. 모든 것이 가까이 모여 있거든요. 골드샤이어의 {n:0::Tharynn Bouden}이 두 요리법과 낚싯대를 모두 팔고, 낚시 전문기술 상급자는 수정 호수에 있어요. 75 이후에 낚시할 스톰윈드도 바로 옆이에요.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "아직 낚시를 배우지 않았다면 수정 호수의 {n:0::Lee Brown}에게서 배우세요.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "골드샤이어의 {n:0::Tharynn Bouden}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}와 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 사세요. {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}도 거기서 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 골드샤이어 동쪽의 수정 호수에서 낚시 숙련도가 75가 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 45마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 30마리를 잡게 될 거예요.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "{n:0::Lee Brown}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 엘윈 숲 골드샤이어 동쪽의 수정 호수",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "아직 낚시를 배우지 않았다면 얼음흐름 호수의 {n:0::Paxton Ganter}에게서 배우세요.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "얼음흐름 호수의 {n:0::Gretta Ganter}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}를 사세요. {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}도 거기서 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 얼음흐름 호수에서 낚시 숙련도가 75가 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 45마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 30마리를 잡게 될 거예요.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "{n:0::Paxton Ganter}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 던 모로의 얼음흐름 호수",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "다르나서스의 {n:0::Astaia}에게서 낚시를 배우세요. 돌라나르에는 낚시 전문기술 상급자가 없어요.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "돌라나르의 {n:0::Nyoma}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}와 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 사세요.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "돌라나르의 {n:0::Narret Shadowgrove}에게서 {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble}을 사세요. (보이는 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}는 모두 사서 나중을 위해 보관하세요.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble}을 단 다음, 돌라나르 남쪽의 알아메스 호수에서 낚시 숙련도가 75가 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 45마리와 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 30마리를 잡게 될 거예요.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "다르나서스의 {n:0::Astaia}에게서 숙련 낚시를 배우세요. 레벨 10이 필요해요.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "1에서 75까지 낚시할 곳, 텔드랏실 돌라나르 남쪽의 알아메스 호수",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "스톰윈드에 도착하면 도시 바로 밖 골드샤이어의 {n:0::Tharynn Bouden}에게서 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}와 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 사세요.",
  ["Fishing (75-130) and Cooking (1-100)"] = "낚시 (75-130) 및 요리 (1-100)",
  ["Fishing"] = "낚시",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "가장 가까운 수도에서 낚시 숙련도가 130이 될 때까지 낚시하세요. 75부터는 어느 수도에서도 물고기를 놓치지 않아요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 20마리, {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 60마리, {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 약 30마리를 잡게 될 거예요.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}썬더 블러프:{/b} 경매장 근처 연못.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}언더시티:{/b} 수로. 여기서 잡히는 것의 약 3분의 1은 잡동사니라서 물고기가 더 적게 나와요.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}오그리마:{/b} 낚시 전문기술 상급자가 있는 명예의 계곡 연못.",
  ["Recipes to buy"] = "구매할 요리법",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "썬더 블러프의 {n:0::Naal Mistrunner}나 언더시티의 {n:0::Ronald Burch}에게서 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}를 사세요. 다음 단계에서 필요해요.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "아직 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}가 없다면 썬더 블러프의 {n:0::Naal Mistrunner}나 언더시티의 {n:0::Lizbeth Cromwell}에게서 사세요.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "오그리마에서는 아무도 팔지 않으니 경매장이나 썬더 블러프에서 사세요.",
  ["Cooking"] = "요리",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "아직 요리를 배우지 않았다면 썬더 블러프의 {n:0::Aska Mistrunner}, 언더시티의 {n:0::Eunice Burch}, 오그리마의 {n:0::Zamja}에게서 배우세요. 그다음 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}를 배우고 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}를 모두 {s:7751:inv_misc_fish_07:Brilliant Smallfish}로 요리하세요. 시작 지역에서 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}을 잡았다면 대신 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}을 배우고 {s:7752:inv_misc_fish_24:Slitherskin Mackerel}로 요리하세요. 이것으로 요리 숙련도가 50이 될 거예요.",
  ["If you are a few points short of 50, catch and cook a few more."] = "50에 몇 포인트 모자라면 몇 마리 더 잡아서 요리하세요.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "같은 전문기술 상급자에게서 숙련 요리를 배우세요. 그다음 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 배우고 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}를 모두 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}로 요리하세요. 요리 숙련도가 100을 넘을 거예요.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "턱긴 진흙퉁돔으로 요리 100에 도달하지 못해도 걱정하지 마세요. 나중에 날 턱긴 진흙퉁돔을 더 잡게 될 거예요.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "스톰윈드 수로에서 숙련도가 130이 될 때까지 낚시하세요. {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 약 20마리, {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 60마리, {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 약 30마리를 잡게 될 거예요.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "스톰윈드에서 {n:0::Catherine Leland}을 찾아 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}를 사세요. 아직 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}가 없다면 골드샤이어의 {n:0::Tharynn Bouden}에게서 사세요.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "{n:0::Ben Trias}도 찾아서 {i:8932:inv_misc_food_37:Alterac Swiss} 20개를 사세요. 나중에 장인 요리 퀘스트에 필요해요.",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "아직 배우지 않았다면 {n:0::Stephen Ryback}에게서 요리를 배우세요. 그다음 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}를 배우고 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}를 모두 {s:7751:inv_misc_fish_07:Brilliant Smallfish}로 요리하세요. 이것으로 요리 숙련도가 50이 될 거예요.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "스톰윈드의 {n:0::Stephen Ryback}에게서 숙련 요리를 배우세요. 그다음 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}를 배우고 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}를 모두 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}로 요리하세요. 요리 숙련도가 100을 넘을 거예요.",
  ["Fishing (130-205) and Cooking (100-175)"] = "낚시 (130-205) 및 요리 (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "전문 낚시는 {b}레벨 20{/b}과 {b}낚시 125{/b}, 전문 요리는 {b}요리 125{/b}가 필요해요.",
  ["Booty Bay"] = "무법항",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "불모의 땅의 톱니항으로 가서 배를 타고 가시덤불 골짜기의 무법항으로 가세요.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "무법항에서 {n:0::Old Man Heming}을 찾아 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You}를 사서 읽으세요.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "{n:0::Kelsey Yance}를 찾아 이 두 요리법을 사세요: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "불모의 땅으로 돌아가서 톱니항에서 돌발톱 산맥의 태양바위 휴양지로 날아간 다음, {n:0::Kulwia}에게서 {i:6530:inv_misc_monstertail_03:Nightcrawlers} 7개를 사세요. 150까지 2개가 필요하고 나머지 5개는 나중을 위해 보관하세요.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "{i:6530:inv_misc_monstertail_03:Nightcrawler}를 달고 탁 트인 물에서 낚시 숙련도가 205가 될 때까지 낚시하세요. {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 95마리와 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 약 145마리를 잡게 될 거예요.",
  ["Fly to Shadowprey Village in Desolace."] = "잊혀진 땅의 그늘사냥꾼 마을로 날아가세요.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "{n:0::Wulan}을 찾아 {i:16072:inv_misc_book_08:Expert Cookbook}을 사세요. 마을 가장 동쪽 건물의 꼭대기 층에 있어요.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "{n:0::Innkeeper Sikewa}에게서 {i:8932:inv_misc_food_37:Alterac Swiss} 20개를 사세요. 장인 요리 퀘스트에 필요해요.",
  ["Leveling Cooking to 175"] = "요리 175까지 올리기",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "요리 숙련도가 아직 100 미만이라면 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}를 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}로 요리하세요.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "특히 자리를 비운 채 요리한다면 {b}125가 되자마자 {i:16072:inv_misc_book_08:Expert Cookbook}을 읽으세요{/b}. 읽지 않으면 150에서 숙련도가 더 오르지 않고 헛되이 요리하게 돼요.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "{i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}를 배우고 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}를 모두 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}로 요리하세요. 요리 숙련도가 175 가까이 오를 거예요.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "뻣뻣수염 메기로 요리 175에 도달하지 못해도 걱정하지 마세요. 나중에 날 뻣뻣수염 메기를 더 잡게 될 거예요.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "가시덤불 골짜기의 무법항으로 가세요.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "불모의 땅으로 가서 톱니항에서 잿빛 골짜기의 아스트라나르로 날아가세요. 남동쪽의 미스트랄 호수로 가서 {n:0::Shandrina}에게서 {i:16072:inv_misc_book_08:Expert Cookbook}과 {i:6530:inv_misc_monstertail_03:Nightcrawlers} 7개를 사세요. 150까지 2개가 필요하고 나머지 5개는 나중을 위해 보관하세요.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "{i:6530:inv_misc_monstertail_03:Nightcrawler}를 달고 미스트랄 호수의 탁 트인 물에서 낚시 숙련도가 205가 될 때까지 낚시하세요. {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 약 95마리와 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 약 145마리를 잡게 될 거예요.",
  ["Artisan Fishing Quest"] = "장인 낚시 퀘스트",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "{i:6530:inv_misc_monstertail_03:Nightcrawlers}가 남지 않았다면 불모의 땅의 {n:0::Kilxx}나 먼지진흙 습지대의 {n:0:alliance:Helenia Olden}에게서 5개를 사세요.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "먼지진흙 습지대로 가서 {b}숙련도가 225가 될 때까지 늪 아무 곳에서나 낚시하세요{/b}. {b}바다에서는 낚시하지 마세요.{/b} 225까지는 낚싯대에 {i:6530:inv_misc_monstertail_03:Nightcrawler}를 계속 달아 두세요. 그렇지 않으면 물고기를 몇 마리 놓쳐요.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "{n:0::Nat Pagle}을 찾아 {q:6607::Nat Pagle, Angler Extreme} 퀘스트를 받으세요. {b}레벨 35{/b}와 {b}낚시 225{/b}가 필요하며, 장인 낚시를 배우려면 이 퀘스트가 필요해요.",
  ["Tidefury Cove, Dustwallow Marsh"] = "먼지진흙 습지대, 성난파도 만",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "퀘스트를 완료하려면 네 지역에서 퀘스트 물고기 4마리를 잡아야 해요:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 페랄라스 (보관해 둔 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}나 페랄라스의 {n:0::Sheendra Tallgrass} / {n:0::Vivianna}가 파는 {i:6532:inv_misc_gem_variety_02:Bright Baubles}를 다세요. 그렇지 않으면 대부분 놓쳐요)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - 슬픔의 늪",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - 잊혀진 땅",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - 가시덤불 골짜기",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Nat Pagle, Angler Extreme 퀘스트 물고기",
  ["Where to catch the four Nat Pagle quest fish"] = "Nat Pagle 퀘스트 물고기 네 마리를 잡는 곳",
  ["Leveling Fishing to 255 and Cooking to 225"] = "낚시 255, 요리 225까지 올리기",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "퀘스트를 완료한 후 {b}먼지진흙 습지대의 늪에서 낚시 숙련도가 255가 될 때까지 계속 낚시하세요.{/b} {b}바다에서는 낚시하지 마세요{/b}. 바다에서는 다음에 요리할 날 미스릴송어 대신 날 바위비늘 대구가 잡혀요.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "담쟁이벽 마을(호드) / 테라모어 섬(얼라이언스)으로 돌아가서 물고기를 요리하거나, 모닥불이 있다면 피우세요.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "요리 숙련도가 아직 175 미만이라면 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}를 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}로 요리하세요.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "{i:17062:inv_scroll_03:Recipe: Mithril Head Trout}를 배우고 225까지 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout}를 {s:20916:inv_misc_fish_02:Mithril Headed Trout}로 요리하세요. 나머지는 장인 요리 퀘스트 후에 요리하니 보관하세요.",
  ["Artisan Cooking Quest"] = "장인 요리 퀘스트",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "타나리스의 가젯잔으로 날아가 {n:0::Dirge Quikcleave}에게서 {q:6610::Clamlette Surprise} 퀘스트를 받으세요. 보상은 장인 요리예요. 퀘스트에는 {b}레벨 35{/b}와 {b}요리 225{/b}가 필요해요. 퀘스트를 완료하려면 다음이 필요해요:",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - 타나리스의 {n:5428::Rocs}, {n:5429::Fire Rocs}, {n:5430::Searing Rocs}가 떨어뜨려요.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - 타나리스의 {n:14123::Steeljaw Snappers}와 {n:5431::Surf Gliders}가 떨어뜨리는 큰입 대합에서 나와요.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - 앞에서 산 것이에요.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "타나리스 스팀휘들 항구의 {n:0::Gikkix}를 찾아 {i:13945:inv_scroll_03:Recipe: Nightfin Soup}를 사세요.",
  ["Fishing to 300 in Feralas"] = "페랄라스에서 낚시 300까지",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "페랄라스의 모자케 야영지(호드) / 페더문 요새(얼라이언스)로 날아가세요.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "{n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}에게서 {i:6530:inv_misc_monstertail_03:Nightcrawlers} 12개를 사세요.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "{i:6530:inv_misc_monstertail_03:Nightcrawler}를 달고 표시된 호수에서 낚시 300이 될 때까지 낚시하세요. 10분마다 새것을 다세요. 페랄라스의 다른 호수나 강도 괜찮지만, {b}제이드미르 호수는 제외예요{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "페랄라스에서 255부터 300까지 낚시할 곳",
  ["Leveling Cooking to 300"] = "요리 300까지 올리기",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "남은 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout}를 250까지 {s:20916:inv_misc_fish_02:Mithril Headed Trout}로 요리하세요.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "{i:13941:inv_scroll_03:Recipe: Filet of Redgill}을 배우고 285까지 {i:13758:inv_misc_fish_06:Raw Redgill}을 {s:18241:inv_misc_fish_06:Filet of Redgill}로 요리하세요.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "{i:13945:inv_scroll_03:Recipe: Nightfin Soup}를 배우고 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper}를 모두 {s:18243:inv_drink_17:Nightfin Soup}로 요리하세요. 수프마다 {i:159:inv_drink_07:Refreshing Spring Water}도 하나씩 필요하니 여관 주인에게서 20개를 사세요.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper}는 오후(게임 시간 12:00-18:00)에는 잡히지 않아요. 오후에 낚시했다면 아마 충분하지 않을 테니, 남은 {i:13758:inv_misc_fish_06:Raw Redgill}도 {s:18241:inv_misc_fish_06:Filet of Redgill}로 요리하세요. 이것으로 300에 도달할 수도 있어요.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "그래도 300에 도달하지 못했다면 오후가 아닌 시간에 조금 더 낚시하거나, 경매장에서 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper}를 몇 마리 사세요.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "이 WoW Forever 요리 숙련도 가이드는 요리 숙련도를 1에서 300까지 가장 빠르고 저렴하게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치, Forever에서 모닥불이 작동하는 방식, 150과 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "요리는 두 개의 전문기술 칸을 차지하지 않아서 모든 캐릭터가 배울 수 있어요. 아래 요리법 대부분은 레벨을 올리면서 얻는 고기나 물고기만 있으면 돼요. 그래서 가이드에는 숙련도 구간마다 몇 가지 요리법을 적어 두었으니 재료가 있는 것을 만들면 돼요. 낚시도 올리고 싶은데 아직 올리지 않았다면 대신 제 낚시 및 요리 숙련도 가이드를 이용하세요:",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "225를 넘으려면 레벨 35가 필요해서 목록을 둘로 나눴어요. 이 부분을 먼저 사세요.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "거대한 알과 짭짤한 조개살은 장인 요리 퀘스트용이에요.",
  ["Cooking Trainer Locations"] = "요리 전문기술 상급자 위치",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "수습 요리는 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요. 모든 전문기술 상급자가 숙련 요리도 가르쳐 주니 50에서 다른 상급자를 찾을 필요가 없어요.",
  ["Orgrimmar: {n:0:horde:Zamja}"] = "오그리마: {n:0:horde:Zamja}",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "언더시티: {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "썬더 블러프: {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "모든 시작 지역에 요리 전문기술 상급자가 있으며, 대부분 여관 안에 있어요.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "칼바위 언덕의 {n:0:horde:Cook Torka}",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "블러드후프 마을 큰 천막 안의 {n:0:horde:Pyall Silentstride}",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "브릴 여관 안의 {n:0:horde:William Pickman}",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "Valanaar의 {n:0::Nyalah Brightfire}, Shen'dar Village의 {n:0::Zerril Softbreeze}",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "스톰윈드: {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "아이언포지: {n:0:alliance:Daryl Riknussun}",
  ["Darnassus: {n:0:alliance:Alegorn}"] = "다르나서스: {n:0:alliance:Alegorn}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "골드샤이어 여관 주방의 {n:0:alliance:Tomas}",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "카라노스 썬더브루 양조장의 {n:0:alliance:Gremlock Pilsnor}",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "돌라나르의 {n:0:alliance:Zarrin}",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "호드와 얼라이언스의 모든 요리 전문기술 상급자는 제 WoW Forever 요리 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Campfire"] = "모닥불",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "요리하려면 모닥불이 필요해요. 요리 전문기술 상급자 옆에 모닥불이 피워져 있는 경우가 많으니 직접 만들기 전에 주위를 둘러보세요.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "Forever에서 모닥불은 아이템이에요. 요리와 함께 {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit}를 배우고 가방에서 모닥불을 설치하기 때문에 미리 키트를 여러 개 만들어 둘 수 있어요. 다른 플레이어가 내 모닥불에 자신의 야영 아이템을 추가할 수도 있어요. 야영 시스템 전체에 대해서는 제 WoW Forever 야영 가이드에서 읽을 수 있어요.",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "키트를 만들려면 {i:4470:inv_tradeskillitem_01:Simple Wood}와 {i:4471:inv_stone_11:Flint and Tinder}가 필요해요. 부싯돌은 키트 제작에만 쓰이고, 모닥불을 설치할 때는 필요 없어요. 아래에서 진영을 열어 전문기술 상급자 근처의 판매 상인을 확인하세요:",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:horde:Xen'to}",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:horde:Ronald Burch}",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:horde:Naal Mistrunner}",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "칼바위 언덕 병영의 {n:0:horde:Jark}",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "블러드후프 마을의 {n:0:horde:Moorat Longstride}",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "브릴의 {n:0:horde:Mrs. Winters}",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "Valanaar의 {n:0::Antelariaa Cloudgaze} Shen'dar Village의 요리 전문기술 상급자 {n:0::Zerril Softbreeze}",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:alliance:Erika Tate}",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:alliance:Emrul Riknussun}",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "전문기술 상급자 옆의 {n:0:alliance:Fyldan}",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "골드샤이어의 {n:0:alliance:Brog Hamfist}",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "썬더브루 양조장의 {n:0:alliance:Kreg Bilmn}",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "돌라나르의 {n:0:alliance:Nyoma}",
  ["Apprentice Cooking (1-50)"] = "수습 요리 (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}이것들은 전문기술 상급자 근처의 요리 용품 상인이 팔아요. 경매장에서 사지 마세요:{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "이 요리법 중 하나로 약 55개를 만드세요. 보통 두 물고기 요리가 가장 저렴해요.",
  ["Food"] = "음식",
  ["Ingredients"] = "재료",
  ["Recipe Source"] = "요리법 출처",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "멀고어: {n:0:horde:Harn Longcast} 썬더 블러프: {n:0:horde:Sewa Mistrunner} 티리스팔 숲: {n:0:horde:Martine Tramblay} 언더시티: {n:0:horde:Lizbeth Cromwell} 던 모로: {n:0:alliance:Gretta Ganter} 엘윈 숲: {n:0:alliance:Tharynn Bouden} 모단 호수: {n:0:alliance:Khara Deepwater} 스톰윈드: {n:0:alliance:Catherine Leland} 텔드랏실: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "듀로타: {n:0:horde:Zansoa} 티리스팔 숲: {n:0:horde:Martine Tramblay} 아이언포지: {n:0:alliance:Tansy Puddlefizz} 텔드랏실: {n:0:alliance:Nessa Shadowsong} 서부 몰락지대: {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "전문기술 상급자",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(호드 전용) {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}가 있다면 {s:15935:inv_misc_food_46:Crispy Bat Wing}을 만드세요. 요리법은 티리스팔 숲의 {n:0:horde:Abigail Shiel}이 팔아요.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(호드 전용) {i:5466:spell_nature_nullifypoison:Scorpid Stinger}가 있다면 {s:6413:inv_misc_food_10:Scorpid Surprise}를 만드세요. 요리법은 듀로타의 {n:0:horde:Grimtak}이 팔아요.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(얼라이언스 전용) {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}가 있다면 {s:6412:inv_misc_food_68:Kaldorei Spider Kabob}을 만드세요. 요리법은 {q:4161::Recipe of the Kaldorei}의 보상이에요. 퀘스트는 텔드랏실의 {n:0:alliance:Zarrin}에게서 받을 수 있어요.",
  ["Journeyman Cooking (50-150)"] = "숙련 요리 (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}전문기술 상급자에게 다시 가서 숙련 요리를 배우세요{/b}. 요리 50이 필요해요.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "특히 자리를 비운 채 요리한다면 {b}다음 단계를 시작하기 전에 꼭 숙련 요리를 배우세요{/b}. 배우지 않으면 75에서 숙련도가 더 오르지 않고 헛되이 요리하게 돼요.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "아래 요리법 중 아무거나로 약 55개를 만드세요. 보통 두 물고기 요리가 가장 저렴해요. {s:8607:inv_misc_food_13:Smoked Bear Meat}는 다른 것보다 빨리 노란색이 되니 더 많이 만들거나, 고기 종류가 여러 개라면 먼저 요리하세요.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "멀고어: {n:0:horde:Harn Longcast} 은빛소나무 숲: {n:0:horde:Killian Sanatha} 썬더 블러프: {n:0:horde:Naal Mistrunner} 언더시티: {n:0:horde:Lizbeth Cromwell} 엘윈 숲: {n:0:alliance:Tharynn Bouden} 아이언포지: {n:0:alliance:Tansy Puddlefizz} 모단 호수: {n:0:alliance:Khara Deepwater} 텔드랏실: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "듀로타: {n:0:horde:Zansoa} 오그리마: {n:0:horde:Shankys} 은빛소나무 숲: {n:0:horde:Killian Sanatha} 언더시티: {n:0:horde:Ronald Burch} 어둠해안: {n:0:alliance:Heldan Galesong} 스톰윈드: {n:0:alliance:Catherine Leland} 텔드랏실: {n:0:alliance:Nessa Shadowsong} 서부 몰락지대: {n:0:alliance:Kriggon Talsone} 저습지: {n:0:alliance:Stuart Fleming} 불모의 땅: {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "은빛소나무 숲: {n:0:horde:Andrew Hilbert} 모단 호수: {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (상인)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "불모의 땅: {n:0:horde:Tari'qa} (호드 전용) {q:2178::Easy Strider Living}의 보상 (얼라이언스 전용)",
  ["Make around 30-35 from one of these two."] = "이 두 가지 중 하나로 약 30-35개를 만드세요.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (약 55개를 사세요. 130-150에서 25개가 더 필요해요)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "힐스브래드 구릉지: {n:0:horde:Derak Nightfall} 썬더 블러프: {n:0:horde:Naal Mistrunner} 썬더 블러프: {n:0:horde:Sewa Mistrunner} 언더시티: {n:0:horde:Ronald Burch} 힐스브래드 구릉지: {n:0:alliance:Lindea Rabonne} 스톰윈드: {n:0:alliance:Catherine Leland} 불모의 땅: {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "스톰윈드: {n:0:alliance:Kendor Kabonka} (얼라이언스 전용)",
  ["Make around 20-25 from any of the recipes below."] = "아래 요리법 중 아무거나로 약 20-25개를 만드세요.",
  ["See above"] = "위 참고",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "스톰윈드: {n:0:alliance:Kendor Kabonka} (얼라이언스) 아라시 고원: {n:0:horde:Keena} (호드)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "불모의 땅: {n:0:horde:Zargh} (호드 전용)",
  ["Expert Cooking (150-225)"] = "전문 요리 (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "전문 요리를 배우려면 요리 125가 된 다음, 잊혀진 땅 그늘사냥꾼 마을의 {n:0:horde:Wulan}(호드)이나 잿빛 골짜기 미스트랄 호수의 {n:0:alliance:Shandrina}(얼라이언스)에게서 {i:16072:inv_misc_book_08:Expert Cookbook}을 사야 해요.",
  ["Make around 25-30 from one of these three."] = "이 세 가지 중 하나로 약 25-30개를 만드세요.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "{s:7755:inv_misc_fish_30:Bristle Whisker Catfish}를 계속 만들어도 되지만 160부터 녹색이라 이 25포인트에 약 90개가 필요해요.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "이 중 하나로 약 55개를 만드세요. 보통 랩터 구이가 가장 저렴해요.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "아라시 고원: {n:0:alliance:Hammon Karwn} 아라시 고원: {n:0:horde:Keena} 먼지진흙 습지대: {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "잿빛 골짜기: {n:0:horde:Wik'Tar} 오그리마: {n:0:horde:Shankys} 가시덤불 골짜기: {n:0::Kelsey Yance} 언더시티: {n:0:horde:Lizbeth Cromwell} 아이언포지: {n:0:alliance:Tansy Puddlefizz} 저습지: {n:0:alliance:Stuart Fleming} 잊혀진 땅: {n:0:horde:Wulan} 어둠해안: {n:0:alliance:Heldan Galesong} 힐스브래드 구릉지: {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "힐스브래드 구릉지 퀘스트 보상 NPC: {n:0:horde:Christoph Jeffcoat}, 퀘스트: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, 퀘스트: {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "장인 요리 (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "장인 요리는 {q:6610::Clamlette Surprise} 퀘스트의 보상이에요. {b}레벨 35{/b}와 {b}요리 225{/b}가 필요해요.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "가젯잔으로 보내는 퀘스트를 받으세요. 호드 플레이어는 오그리마의 {n:0:horde:Zamja}에게서 {q:6611::To Gadgetzan You Go!}를, 얼라이언스 플레이어는 아이언포지의 {n:0:alliance:Daryl Riknussun}에게서 {q:6612::I Know A Guy...}를 받으세요.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat}, 20x {i:8932:inv_misc_food_37:Alterac Swiss}를 모으세요. {b}모두 모으기 전에는 가젯잔에 가지 마세요{/b}. 그렇지 않으면 두 번 가야 해요.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "가젯잔에서 {n:0::Dirge Quikcleave}를 찾아 Clamlette Surprise를 받고 세 가지 아이템을 넘겨주세요. 그 자리에서 장인 요리를 가르쳐 줘요. 타나리스에 있는 동안 스팀휘들 항구로 가서 {b}{n:0::Gikkix}에게서 {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail}을 사세요{/b}. 다음 단계에서 필요해요.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "이 두 가지 중 하나로 약 140개를 만드세요. 더 저렴한 물고기를 사세요.",
  ["Tanaris: {n:0::Gikkix}"] = "타나리스: {n:0::Gikkix}",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "가시덤불 골짜기: {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "이 WoW Forever 응급치료 숙련도 가이드는 응급치료 숙련도를 1에서 300까지 가장 빠르게 올리는 방법을 알려드려요. 모든 전문기술 상급자의 위치와 150, 225 이상을 배울 수 있는 곳도 확인할 수 있어요.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "응급치료는 두 개의 전문기술 칸을 차지하지 않아서 모든 캐릭터가 배울 수 있어요. 붕대로 전투 사이에 체력을 회복할 수 있고, Forever에서는 예전에 연금술 제조법이었던 치유 물약도 응급치료로 만들기 때문에 모든 캐릭터에서 올릴 가치가 있어요. 아래에서 구매 목록, 시작 지역과 수도별 응급치료 전문기술 상급자, 그리고 숙련도 구간별로 가장 저렴한 제조법을 확인할 수 있어요.",
  ["First Aid Trainer Locations"] = "응급치료 전문기술 상급자 위치",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "수습 응급치료는 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요. 모든 전문기술 상급자가 숙련 응급치료도 가르쳐 주니 50에서 다른 상급자를 찾을 필요가 없어요.",
  ["Orgrimmar: {n:0:horde:Arnok}"] = "오그리마: {n:0:horde:Arnok}",
  ["Undercity: {n:0:horde:Mary Edras}"] = "언더시티: {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "썬더 블러프: {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "모든 시작 지역에 응급치료 전문기술 상급자가 있으며, 대부분 여관 안에 있어요.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "칼바위 언덕 병영의 {n:0:horde:Rawrk}",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "블러드후프 마을 여관 안의 {n:0:horde:Vira Younghoof}",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "브릴 여관 안의 {n:0:horde:Nurse Neela}",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "Valanaar의 {n:0::Melasa Fairmend}, Shen'dar Village의 {n:0::Naleeia Tattermend}",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "스톰윈드: {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "아이언포지: {n:0:alliance:Nissa Firestone}",
  ["Darnassus: {n:0:alliance:Dannelor}"] = "다르나서스: {n:0:alliance:Dannelor}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "골드샤이어 여관 위층의 {n:0:alliance:Michelle Belle}",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "카라노스 썬더브루 양조장의 {n:0:alliance:Thamner Pol}",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "돌라나르 여관 북쪽 건물의 {n:0:alliance:Byancie}",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "호드와 얼라이언스의 모든 응급치료 전문기술 상급자는 제 WoW Forever 응급치료 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["Apprentice First Aid (1-75)"] = "수습 응급치료 (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "리넨 옷감이 있거나 샀다면 {b}붕대{/b} 탭을, 약초를 샀다면 {b}치유 물약{/b} 탭을 선택하세요.",
  ["Bandages"] = "붕대",
  ["Healing Potions"] = "치유 물약",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 평온초 86개, 순한 향신료 86개, 빈 약병 86개",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices}는 요리 용품 상인이, {i:3371:inv_potion_84:Empty Vial}은 연금술 재료 상인이 팔아요. 아래에서 진영을 열어 전문기술 상급자 근처의 판매 상인을 확인하세요:",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "향신료: {n:0:horde:Xen'to} 약병: {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "상업 지구의 {n:0:horde:Felicia Doan}",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "향신료: {n:0:horde:Naal Mistrunner} 약병: {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "블러드후프 마을의 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "브릴의 {n:0:horde:Abigail Shiel}",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "Valanaar의 {n:0::Iallion Featherfall} Shen'dar Village의 {n:0::Belandiel Farflight}",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "상업 지구의 {n:0:alliance:Edna Mullby}",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "향신료: {n:0:alliance:Emrul Riknussun} 약병: {n:0:alliance:Gwina Stonebranch}, 전문기술 상급자 바로 옆",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "카라노스의 {n:0:alliance:Golorn Frostbeard}",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "돌라나르의 {n:0:alliance:Narret Shadowgrove}",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 리넨 옷감 50개",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 리넨 옷감 98개",
  ["Journeyman First Aid (75-150)"] = "숙련 응급치료 (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "75 이상을 배우려면 전문기술 상급자에게 가서 숙련 응급치료를 배우세요. 응급치료 50이 필요해요.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 리넨 옷감 32개",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 양모 옷감 12개",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "양모 옷감이 있다면 {b}붕대{/b} 탭을 선택하세요. 모두 사야 한다면 {b}치유 물약{/b} 탭이 더 저렴해요.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 양모 옷감 43개",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 양모 옷감 108개",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "이 탭에는 {i:2678:inv_misc_food_wheat_02:Mild Spices} 54개, {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices} 31개, {i:3372:inv_potion_85:Leaded Vial} 31개, {i:2723:inv_drink_10:Bottle of Dalaran Noir} 54개가 필요해요. 향신료는 요리 용품 상인이, 약병은 연금술 재료 상인이, 병은 주점 주인이 팔아요. 시작 지역 상인은 매운 향신료와 납 약병을 팔지 않으니 수도에서 사세요. 아래에서 진영을 열어 판매 상인을 확인하세요:",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices}와 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "오그리마: {n:0:horde:Xen'to} 언더시티: {n:0:horde:Felicia Doan} 썬더 블러프: {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "오그리마: {n:0:horde:Kor'geld} 언더시티: {n:0:horde:Felicia Doan} 썬더 블러프: {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "오그리마: {n:5611::Barkeep Morag} 무법항: {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "스톰윈드: {n:0:alliance:Edna Mullby} 아이언포지: {n:0:alliance:Emrul Riknussun} 다르나서스: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "스톰윈드: {n:0:alliance:Edna Mullby} 아이언포지: {n:0:alliance:Gwina Stonebranch} 다르나서스: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "스톰윈드: {n:277::Roberto Pupellyverbos}와 {n:1328::Elly Langston} 아이언포지: {n:5570::Bruuk Barleybeard} 무법항: {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 거미 체액 54개, 순한 향신료 54개, 달라란 흑포도주 54개",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 생채기풀 31개, 매운 향신료 31개, 납 약병 31개",
  ["Expert First Aid (150-225)"] = "전문 응급치료 (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}떠나기 전에 전문기술 상급자에게서 {s:7928:inv_misc_bandage_01:Silk Bandage}를 배우세요{/b}. 상급자가 가르쳐 주는 마지막 제조법이에요.",
  ["How to learn Expert First Aid"] = "전문 응급치료 배우는 방법",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "150 이상을 배우려면 아라시 고원의 {n:0:alliance:Deneb Walker}(얼라이언스)나 먼지진흙 습지대의 {n:0:horde:Balai Lok'Wein}(호드)에게서 {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} 책을 사세요. 이 책은 {b}레벨 제한이 없고{/b} 응급치료 125만 있으면 돼요.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "다음 교본 두 권도 팔기 때문에 거기 있는 동안 {b}세 권 모두 사세요{/b}. 레벨이 낮다면 경매장에서 구해도 돼요:",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 비단 옷감 47개",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 비단 옷감 94개",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "먼저 교본: 두꺼운 비단 붕대를 사용해서 제조법을 배우세요.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 마법 옷감 19개",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "먼저 교본: 마법 붕대를 사용해서 제조법을 배우세요.",
  ["Artisan First Aid (225-300)"] = "장인 응급치료 (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "부상자 분류 퀘스트를 완료하면 225 이상의 응급치료를 배울 수 있어요. 퀘스트 자체는 레벨 45지만 {b}응급치료 225{/b}와 {b}레벨 35{/b}가 필요해요.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "다음 두 붕대도 같은 의사에게서 배우기 때문에 {b}275까지 올리는 데 필요한 것을 모두 챙겨 가세요{/b}. 마법 옷감 약 90개와 룬매듭 옷감 20개를 가져가세요.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "{q:6622::Triage} 퀘스트는 아라시 고원 해머폴의 {n:0:horde:Doctor Gregory Victor}가 줘요.",
  ["Hammerfall, Arathi Highlands"] = "아라시 고원, 해머폴",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "{q:6624::Triage} 퀘스트는 먼지진흙 습지대 테라모어의 {n:0:alliance:Doctor Gustaf VanHowzen}이 줘요.",
  ["Foothold Citadel, Dustwallow Marsh"] = "먼지진흙 습지대, 거점 성채",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "부상자 분류용 붕대 한 묶음을 받고 환자 15명을 구해야 해요. 위독한 환자부터 치료하세요.",
  ["How to complete the Triage quest"] = "부상자 분류 퀘스트 완료 방법",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "방해받지 않고 할 수 있도록 10분 정도 여유 시간을 꼭 확보하세요.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "CTRL + V를 눌러 환자 위에 생명력 바를 표시하거나, 인터페이스 설정에서 \"NPC 이름 표시\"를 켜세요.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "카메라를 3인칭으로 멀리 빼서 방을 최대한 넓게 볼 수 있게 하세요.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "의사가 준 부상자 분류용 붕대를 행동 단축바에 올려 그것을 쓰세요. 자신의 붕대는 쓰지 마세요.",
  ["Stand in the middle of the room."] = "방 가운데에 서세요.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "다른 환자가 보이면 왼쪽 클릭으로 미리 선택해 두고, 현재 치료가 끝나자마자 행동 단축바의 붕대를 클릭하면 미리 선택한 환자 치료가 시작돼요. 이렇게 하면 귀중한 몇 초를 아낄 수 있어요.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "환자 15명을 구했다면 {b}바로 퀘스트를 완료하세요{/b}. 저는 드루이드로 기다리다가 그사이 환자 여섯 명이 죽어서 퀘스트가 완료에서 실패로 바뀌었어요.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 마법 옷감 29개",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 마법 옷감 60개",
  ["The doctor teaches it at 240."] = "의사가 240에서 가르쳐 줘요.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 룬매듭 옷감 20개",
  ["The doctor teaches it at 260."] = "의사가 260에서 가르쳐 줘요.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 황금 산삼 30개, 진정 효과 향신료 90개, 수정 약병 30개",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "제조법은 {i:255729:inv_misc_book_03:Manual: Major Healing Potion}이에요. 먼저 경매장을 확인하고 8골드보다 싸면 거기서 사세요.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "더 비싸다면 하이잘 산의 {n:0::Pexmit}에게서 8골드에 살 수 있지만, 찾기가 좀 까다로울 수 있어요.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "호드 플레이어는 하이잘 산 Elderwild의 Ortak Lomgok에게서 {q:96622::A Rest Without Pain}의 보상으로도 얻을 수 있어요. 먼저 그의 {q:96616::Herbs for the Bruised and Weary} 퀘스트를 완료해야 해요.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "이 WoW Forever 낚시 숙련도 가이드는 낚시를 1에서 300까지 가장 빠르게 올리는 방법을 알려드려요. 낚시는 인내심이 많이 필요해요. 처음부터 끝까지 물고기를 아주 많이 잡아야 하지만, 재료는 필요 없고 낚싯대와 미끼 몇 개만 있으면 돼요.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "아래에서 시작 지역과 수도별 낚시 전문기술 상급자, 숙련도 구간별 낚시 장소, 그리고 전문 및 장인 낚시를 배우는 방법을 확인할 수 있어요. 아직 요리를 올리지 않았다면 대신 제 낚시 및 요리 숙련도 가이드를 이용하세요. 잡은 물고기로 요리도 동시에 올릴 수 있거든요:",
  ["Fishing Trainer Locations"] = "낚시 전문기술 상급자 위치",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "Forever에서는 수습 낚시에 레벨 제한이 없어서 새 캐릭터로도 배울 수 있어요. 모든 전문기술 상급자가 숙련 낚시도 가르쳐 주니 50에서 다른 상급자를 찾을 필요가 없어요.",
  ["Orgrimmar: {n:0:horde:Lumak}"] = "오그리마: {n:0:horde:Lumak}",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "언더시티: {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "썬더 블러프: {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "모든 시작 지역에 낚시 전문기술 상급자가 있고 모두 물가에 서 있어서 바로 낚시를 시작할 수 있어요.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "센진 마을 해안의 {n:0:horde:Lau'Tiki}",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "블러드후프 마을 옆 스톤불 호수의 {n:0:horde:Uthan Stillwater}",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "브릴 동쪽 맑은물 호수의 {n:0:horde:Clyde Kellen}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "Valanaar의 {n:0::Baelann Swiftcurrent}, Shen'dar Village의 {n:0::Fenn Fairweather}",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "스톰윈드: {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "아이언포지: {n:0:alliance:Grimnur Stonebrand}",
  ["Darnassus: {n:0:alliance:Astaia}"] = "다르나서스: {n:0:alliance:Astaia}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "골드샤이어 동쪽 수정 호수의 {n:0:alliance:Lee Brown}",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "놈리건으로 가는 길의 얼음흐름 호수에 있는 {n:0:alliance:Paxton Ganter}",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "루테란 마을 부두 옆 물가의 {n:0:alliance:Androl Oakhand}",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "호드와 얼라이언스의 모든 낚시 전문기술 상급자는 제 WoW Forever 낚시 전문기술 상급자 페이지에서 확인할 수 있어요.",
  ["How to Fish in WoW Forever (1-75)"] = "WoW Forever에서 낚시하는 방법 (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "낚시 용품 상인이나 잡화 상인에게서 {i:6256:inv_fishingpole_02:Fishing Pole}와 {i:6529:inv_misc_orb_03:Shiny Bauble} 몇 개를 사세요. 수도에서는 전문기술 상급자 옆에 있고, 다른 지역은 아래에서 진영을 여세요:",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "센진 마을의 {n:0:horde:Zansoa}",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "브릴 남동쪽 죽음의 감시 간이역의 {n:0:horde:Martine Tramblay}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "Valanaar의 {n:0::Baelann Swiftcurrent}, Shen'dar Village의 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:horde:Shankys}",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:horde:Lizbeth Cromwell}",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:horde:Sewa Mistrunner}",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "조람가르 전초기지의 {n:0:horde:Wik'Tar}",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "레반터스크 마을의 낚시 전문기술 상급자 {n:0:horde:Katoom the Angler}",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "얼음흐름 호수의 {n:0:alliance:Gretta Ganter}",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "루테란 마을의 {n:0:alliance:Nessa Shadowsong}",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:alliance:Catherine Leland}",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:alliance:Tansy Puddlefizz}",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "낚시 전문기술 상급자 옆의 {n:0:alliance:Voloren}",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "호수의 {n:0:alliance:Khara Deepwater}",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "메네실 항구의 {n:0:alliance:Stuart Fleming}",
  ["Redridge Mountains"] = "붉은마루 산맥",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "영원고요 호수의 {n:0:alliance:Vernon Hale}",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "사우스쇼어의 {n:0:alliance:Lindea Rabonne}",
  ["Open the Professions window."] = "전문기술 창을 여세요.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "화면 오른쪽 버튼 줄의 {b}망치 버튼{/b}을 클릭하세요. {b}낚시 탭이 아니에요{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "낚시 칸의 {s:7731:trade_fishing:Fishing} 버튼을 행동 단축바로 끌어다 놓으세요.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "낚싯대를 장착하고 {i:6529:inv_misc_orb_03:Shiny Bauble} 미끼를 다세요.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "아무 시작 지역에 가서 호수, 연못, 강을 찾으세요. 물 앞에 서서 낚시 버튼을 누르세요.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "물 위의 찌에 마우스를 올리고, 물이 튀면 오른쪽 클릭하세요.",
  ["Fish until you reach Fishing 75."] = "낚시 75가 될 때까지 낚시하세요.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}시작 지역:{/b} 던 모로, 듀로타, 엘윈 숲, 멀고어, 텔드랏실, 티리스팔 숲, Zephras Isle",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}시작 지역에 수도는 포함되지 않는다는 것을 기억하세요!{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "낚시 버튼을 찾을 수 없다면 제 WoW Forever 낚시 방법 가이드에서 그림으로 보여 드려요.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "전문기술 상급자에게 돌아가서 숙련 낚시를 배우세요. {b}낚시 50{/b}과 {b}레벨 10{/b}이 필요해요.",
  ["Fish until 150 in one of the capital cities:"] = "수도 중 한 곳에서 150까지 낚시하세요:",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "이 지역에서 낚시해도 돼요: 불모의 땅, 어둠해안, 아이언포지, 모단 호수, 은빛소나무 숲, 서부 몰락지대.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "물고기를 계속 놓친다면 낚시 용품 상인에게서 {i:6530:inv_misc_monstertail_03:Nightcrawlers}를 사세요. 낚시 50이 필요해요.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "전문 낚시는 가시덤불 골짜기 무법항의 {n:0::Old Man Heming}이 파는 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} 책({b}레벨 20{/b}과 {b}낚시 125{/b} 필요)으로 배울 수 있어요. 그는 무법항 한가운데 맨 아래쪽, 낚시 간판 근처에 있어요. 책은 경매장에서 살 수도 있어요.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "떠나기 전에 Old Man Heming에게서 {i:6532:inv_misc_gem_variety_02:Bright Baubles}를 넉넉히 사세요.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "{b}먼지진흙 습지대{/b}로 가서 낚싯대에 {i:6532:inv_misc_gem_variety_02:Bright Baubles}를 달고 225까지 낚시하세요.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "장인 낚시 퀘스트가 먼지진흙 습지대에서 시작되기 때문에 거기서 낚시하는 것을 추천하지만, 이 지역에서 낚시해도 돼요: 알터랙 산맥, 아라시 고원, 잊혀진 땅, 가시덤불 골짜기, 슬픔의 늪, 버섯구름 봉우리.",
  ["Learning Artisan Fishing"] = "장인 낚시 배우기",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "225 이상의 낚시를 배우려면 먼지진흙 습지대의 {n:0::Nat Pagle}에게서 {q:6607::Nat Pagle, Angler Extreme} 퀘스트를 완료해야 해요.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "{b}레벨 35{/b}와 {b}낚시 225{/b}가 필요해요.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "퀘스트를 완료하려면 네 지역에서 퀘스트 물고기 4마리를 잡아야 해요:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 페랄라스",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "{b}페랄라스{/b}에서 낚시할 때는 물고기를 놓치지 않도록 {i:6532:inv_misc_gem_variety_02:Bright Baubles}를 쓰세요. 다른 지역에서는 그때쯤 낚시 숙련도가 충분히 높아서 미끼가 필요 없어요.",
  ["Nat Pagle, Angler Extreme quest"] = "Nat Pagle, Angler Extreme 퀘스트",
  ["After you completed the quest, fish in any of these zones:"] = "퀘스트를 완료한 후 이 지역 중 아무 곳에서나 낚시하세요:",
  ["Feralas"] = "페랄라스",
  ["Western Plaguelands"] = "서부 역병지대",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "이 지역에서는 물고기를 놓치지 않도록 {i:6532:inv_misc_gem_variety_02:Bright Baubles}를 써야 해요!",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "이 WoW Forever 자물쇠 따기 숙련도 가이드는 자물쇠 따기를 1에서 300까지 가장 빠르게 올리는 방법과 숙련도 구간별로 자물쇠를 따기 가장 좋은 장소를 알려드려요.",
  ["Max Lockpicking Skill by Level"] = "레벨별 최대 자물쇠 따기 숙련도",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}자물쇠 따기 숙련도는 레벨의 5배를 넘을 수 없어요{/b}. 그래서 자물쇠 따기를 올리려면 캐릭터 레벨을 올려야 해요. 가이드의 각 부분에 필요한 레벨은 다음과 같아요:",
  ["Your level"] = "내 레벨",
  ["Max Lockpicking skill"] = "최대 자물쇠 따기 숙련도",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "이 가이드는 원래 클래식에서 제 도적으로 만들었어요. WoW Forever에서는 사냥꾼을 키우고 있어서 친구가 자기 도적으로 장소를 확인해 주는데, 호드 1-100 부분은 친구가 확인했어요. 150에서 300까지는 독자분들이 어디서 올렸는지 알려 주셨어요. 나머지는 클래식과 같다고 가정하고 있지만 나중에 확인할게요. 이상한 점이 있으면 피드백을 보내 주세요.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "불모의 땅 톱니항 근처의 배로 가세요. 그곳의 해적의 금고는 몇 초 후에 재생성되어서 도적 두 명이 동시에 올려도 돼요. {b}배 안에 있어요{/b}. 아래 지도에 표시한 위치예요.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "배 맨 아래에 남쪽바다의 보석이라는 상자가 하나 더 있어요. 레벨이 낮다면 열지 마세요. 몹이 나타나서 죽게 될 거예요.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "붉은마루 산맥 영원고요 호수 북쪽에 연습용 자물쇠 상자가 많이 있어요. 아주 빨리 재생성되어서 거기서 100까지 쉽게 올릴 수 있어요.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "잿빛 골짜기의 조람 해안으로 가서 해안가 땅 위에 있는 물에 젖은 사물함을 찾으세요.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "황야의 땅의 앙거 요새로 가세요. 그곳에는 두 종류의 사물함이 있는데, 위층의 낡은 사물함은 150, 아래층의 찌그러진 사물함은 {b}175{/b}가 필요해요.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "아래층의 사물함은 215까지 매번 숙련도가 오르기 때문에 225까지 여기 있어도 돼요.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "그곳 몹의 소매치기는 하지 마세요. 상자 레벨이 너무 낮아서 숙련도가 오르지 않아요.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "이글거리는 협곡 한가운데 동굴인 용재 구덩이로 가서 사물함을 따세요. 위쪽에 있는 것은 300까지 숙련도가 올라요. 290까지 노란색이다가 그 뒤로 녹색이 되기 때문에 마지막 10포인트는 더 오래 걸려요.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}용재 구덩이에는 이름이 같은 찌그러진 사물함이 두 종류 있어요{/b}. 아래쪽 것은 200, 위쪽 것은 225가 필요해요. 아래쪽 것이 숙련도를 더 주지 않을 때까지 둘 다 따고, 그다음엔 위쪽에 머무르세요.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "그곳 몹의 소매치기는 하지 마세요. 상자 레벨이 너무 낮아서 숙련도가 별로 오르지 않아요.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "이 WoW Forever 야영 가이드는 야영이 어떻게 작동하는지, 모닥불을 만드는 방법, 그리고 모든 전문기술의 야영 아이템과 버프를 알려드려요.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "WoW Forever, 텔드랏실 돌라나르의 모닥불에 앉아 있는 나이트 엘프 세 명",
  ["How Camping Works"] = "야영 작동 방식",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "누군가 모닥불을 피우면, 주변의 모든 사람이 자신의 전문기술 야영 아이템을 하나씩 설치할 수 있어요. {b}모닥불 옆에 1분 동안 앉아 있으면(/sit){/b} 버프의 카운트다운이 시작되는 것이 보여요. 그러면 야영 아이템이 주는 모든 효과가 담긴 버프 하나인 야영 혜택을 1시간 동안 받아요.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}플레이어마다 야영 아이템을 하나씩 설치할 수 있고{/b}, 설치하면 모든 야영 아이템에 1시간 재사용 대기시간이 걸려요. 모닥불 크기에 따라 야영 아이템을 3개, 5개 또는 10개까지 둘 수 있어요(아래의 모닥불 만드는 방법 참고). 버프는 직업 버프보다 약하고, 직업 버프와 중첩되지 않아요.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "시작 지역의 입문 퀘스트인 The Great Outdoors와 Camping 101은 선택 사항이며, 버프는 이 퀘스트 없이도 작동해요. 퀘스트 제공자의 모닥불은 항상 야영 천막의 휴식 경험치를 줘요.",
  ["How to Make a Campfire"] = "모닥불 만드는 방법",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "아무 요리 전문기술 상급자에게서 요리를 배우세요. 숙련도 1에서 기본 모닥불 키트가 함께 주어져요. {i:4470:inv_tradeskillitem_01:Simple Wood}는 대부분 마을의 잡화 상인이 팔아요. 전문기술 창(메뉴 바의 망치와 곡괭이 버튼)을 열고 요리 항목에서 평범한 목재 1개로 키트를 만든 다음, 가방에서 사용해 모닥불을 설치하세요.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}팁:{/b} 이제 부싯돌과 목재를 들고 다닐 필요가 없어요. 집에서 기본 모닥불 키트를 한 묶음 만들어서 그것만 가지고 다니세요. 가방 한 칸만 차지해요. 다른 사람에게 줄 수도 있어요.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "더 큰 모닥불은 야영 아이템을 더 많이 둘 수 있지만 청사진이 필요해요.",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "전문가 모닥불 키트는 배울 때보다 사용할 때 더 높은 요리 숙련도가 필요해요(200 대신 220). 보통은 반대라서 버그일 수도 있어요.",
  ["Learn at"] = "배우는 숙련도",
  ["Use at"] = "사용 숙련도",
  ["Camp items"] = "야영 아이템",
  ["Made from"] = "재료",
  ["Comes with Cooking"] = "요리와 함께 배움",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} 드롭: 통곡의 동굴의 {n:3673::Lord Serpentis}",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} 어디서 드롭되는지 아직 모르겠어요",
  ["Camp Items"] = "야영 아이템",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "모든 전문기술에는 숙련도 20, 140, 300에 야영 아이템이 세 개씩 있고(요리는 두 개), 각각 이전 것을 대체해요. 1단계 아이템은 전문기술 상급자에게서 얻고, {b}2단계와 3단계는 제조법 아이템인 청사진이 필요해요{/b}. 2단계와 3단계 청사진은 우두머리에게서 드롭되며 대부분 던전에 있어요. 탭에서 어떤 우두머리인지 확인할 수 있어요. 300의 약초채집 청사진만 아직 알려지지 않았어요.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}모든 아이템은 해당 전문기술 1단계 아이템의 버프도 함께 줘요{/b}. 그래서 버프와 제작대 중 하나를 고를 필요가 없어요. 고급 용광로도 여전히 숫돌의 힘 버프를 줘요. 3단계 아이템이 2단계 아이템의 효과(고급 용광로의 모루)도 주는지는 아직 확인되지 않았어요. 탭에는 각 단계에서 추가되는 것만 나와 있어요.",
  ["Alchemy"] = "연금술",
