  ["Camp Item"] = "야영 아이템",
  ["What It Does"] = "효과",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "마나 회복 버프, 지혜의 축복과 중첩되지 않음",
  ["Trainer or the Camping 101 quest"] = "전문기술 상급자 또는 Camping 101 퀘스트",
  ["A Fermenter, needed for a few Alchemy recipes"] = "일부 연금술 제조법에 필요한 발효기",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} 드롭: 로데론의 폐허의 {n:250657::Rath'mael}",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "일부 연금술 제조법에 필요한 연금술 실험실",
