  ["+25 Strength and 2% crit for 30 min"] = "30분 동안 힘 +25, 치명타 2%",
  ["{n:0:horde:Gor'mak} at the Horde camp and {n:0:alliance:Stondry Darkhammer} at the Alliance camp sell 61 Blacksmithing recipes."] = "호드 야영지의 {n:0:horde:Gor'mak}와 얼라이언스 야영지의 {n:0:alliance:Stondry Darkhammer}가 대장기술 도안 61개를 팔아요.",
  ["Tank"] = "방어 전담",
