  ["Two-Hand Polearm"] = "양손 장창",
  ["Two-Hand Mace"] = "양손 둔기",
  ["{n:0:horde:Aza'bek} at the Horde camp and {n:0:alliance:Kalsey Sanden} at the Alliance camp sell 6 Cooking recipes (all of them mana drinks)."] = "호드 야영지의 {n:0:horde:Aza'bek}와 얼라이언스 야영지의 {n:0:alliance:Kalsey Sanden}이 요리법 6개를 팔아요(모두 마나 음료).",
  ["+1 Spirit for 15 min"] = "15분 동안 정신력 +1",
